INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5298', 'spa', 'Nefeg; nombre propio de un levita (Éx 6:21) y de un hijo de David (2 S 5:15; 1 Cr 3:7; 14:6)', 'Nefeg aparece como nombre de dos individuos distintos en las Escrituras. El primero es un levita mencionado en los registros genealógicos de Éxodo 6:21. El segundo, más destacado, es un hijo de David nacido en Jerusalén, registrado tanto en Samuel como en Crónicas. La etimología del nombre es incierta, aunque BDB señala variantes en las transliteraciones griegas según los manuscritos. Las traducciones a distintos idiomas mantienen formas notablemente estables del nombre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5299b', 'spa', 'Altura, región elevada; forma constructa en el topónimo «Nafot-dor»', 'Este sustantivo femenino designa un área elevada o altura, y aparece únicamente en la denominación geográfica «Nafot-dor» (alturas o crestas de Dor). El término describe el terreno montañoso que rodea la antigua ciudad cananea de Dor en la costa mediterránea. Josué conquistó al rey de esta región (Josué 11:2; 12:23), y Salomón la organizó más tarde como distrito administrativo (1 Reyes 4:11). La palabra aparece siempre en forma constructa, vinculada a «Dor», lo que sugiere que era un término geográfico técnico para el terreno elevado característico de esa zona costera.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5301', 'spa', 'Soplar, respirar; soplar sobre brasas o dentro de algo; resoplar con desprecio; expirar; hacer exhalar', 'En su esencia, este verbo captura el acto de soplar con propósito — aire dirigido con intención. Su uso teológicamente más trascendental es Génesis 2:7, donde Dios «sopló en» las narices de Adán el aliento de vida. La misma raíz describe el soplar de fuelles para calentar hornos (Ez 22:20-21), una olla «soplada» hasta hervir (Jer 1:13), y en una imagen conmovedora retrata a una madre afligida que «exhala su alma» al ponerse el sol (Jer 15:9). También puede expresar desprecio: los sacerdotes de Malaquías 1:13 «soplan con desdén» sobre la mesa del SEÑOR.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5303', 'spa', 'Nefilim, gigantes; seres antediluvianos y cananeos de tamaño extraordinario', 'Este enigmático sustantivo plural designa a los «gigantes» que aparecen tanto antes del Diluvio (Génesis 6:4) como en Canaán durante la peregrinación de Israel por el desierto (Números 13:33, dos veces). La etimología es incierta, posiblemente derivada de una raíz que significa «caer» (¿los caídos? ¿los que hacen caer a otros?). Los traductores antiguos emplearon «gigantes» (griego γίγαντες, latín), mientras que los intérpretes modernos debaten si el término alude a estatura física, carácter violento u origen semidivino. En Números, los espías aterrados informan haber visto descendientes de los nefilim entre los anaceos, utilizando a estos gigantes como símbolo máximo de la inexpugnabilidad de Canaán.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5305', 'spa', 'Nafis, hijo de Ismael y ancestro epónimo de una tribu árabe', 'Este nombre propio identifica a uno de los doce hijos de Ismael, mencionado tanto en Génesis 25:15 como en 1 Crónicas 1:31 entre los ancestros tribales árabes. El nombre también designa a la tribu descendiente de él, a la cual las tribus transjordanas de Rubén, Gad y Manasés derrotaron en batalla (1 Crónicas 5:19). Las transliteraciones griegas varían (Ναφες, Ναφεις), y el nombre probablemente tiene cognados árabes, en consonancia con la identidad de Ismael como padre de los pueblos árabes. La tribu de Nafis habitaba territorio al este del Jordán antes de la conquista israelita.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5306', 'spa', 'piedra preciosa, posiblemente turquesa, rubí o carbunclo; aparece en el pectoral del sumo sacerdote y en descripciones simbólicas', 'Esta gema figura en el pectoral del sumo sacerdote (Éxodo 28:18; 39:11) y en las descripciones simbólicas de la riqueza de Tiro en Ezequiel. Las versiones antiguas discrepan sobre su identificación exacta: el griego y la Vulgata sugieren carbunclo o rubí (ἄνθραξ, carbunculus), mientras que el Targum se inclina por la esmeralda. Los estudiosos modernos suelen proponer la turquesa. Esta incertidumbre refleja la dificultad de equiparar la terminología antigua de gemas comerciales con la mineralogía actual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5307', 'spa', 'Caer, caer postrado; echar suertes; desertar; atacar; desmontar; causativo: derribar, echar a suertes, repartir.', 'El sentido primario es la caída física — desplomarse al suelo por agotamiento, muerte o postración. Pero נָפַל se extiende mucho más allá del simple movimiento descendente. Abarca la deserción militar (caer al bando enemigo), la postración ritual (caer en adoración) y el lanzamiento de suertes para la adivinación o el reparto de tierras. El Hifil causativo puede significar ''hacer caer'' (derribar al enemigo), ''echar suertes'' (arrojar piedras o dados) o ''repartir la tierra'' (distribuir por sorteo). Incluso ''desmontar'' de un camello aparece como sentido especializado, donde el movimiento descendente es controlado y no accidental.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5308', 'spa', 'Caer, caer postrado (arameo) — caer en adoración, derrumbarse o descender sobre alguien', 'El verbo arameo נְפַל (nepal) significa caer o caer postrado, y se usa casi exclusivamente en Daniel. Su empleo más destacado describe la postración ante un ídolo: cuando suena la música, todos los pueblos deben «caer y adorar» la imagen de Nabucodonosor (Dn 3:5-7, 10-11, 15). El propio Nabucodonosor cae rostro en tierra ante Daniel (Dn 2:46). Los tres amigos caen atados al horno (Dn 3:23). Una voz celestial «cae» sobre el rey como pronunciamiento divino (Dn 4:28). Daniel 7:20 lo usa para cuernos que caen ante el cuerno pequeño.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5309', 'spa', 'Aborto, criatura nacida muerta; feto expulsado prematuramente que nunca llegó a vivir', 'Este sustantivo designa a un niño abortado o nacido muerto, aquel que nunca respiró ni vio la luz. Job desea haber sido «como aborto escondido, como los pequeños que nunca vieron la luz» (Job 3:16), prefiriendo la no existencia a su sufrimiento. El salmista pide a Dios que los malvados se deshagan «como el aborto de mujer» que se disuelve antes de nacer (Salmo 58:8). Eclesiastés lo emplea para argumentar que incluso el nacido muerto, sin nombre ni conocimiento, tiene más reposo que quien vive largamente sin satisfacción. La palabra evoca la pérdida más trágica de la vida: un potencial truncado, un comienzo que termina antes de comenzar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5310a', 'spa', 'Destrozar, hacer pedazos, quebrantar con violencia; en Piel, aplastar enemigos u objetos; en voz pasiva, ser quebrantado o dispersado', 'Destrozar, hacer pedazos, quebrantar con violencia; en Piel, aplastar enemigos u objetos; en voz pasiva, ser quebrantado o dispersado');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5310b', 'spa', 'dispersar, ser esparcido; usado para describir la dispersión de pueblos o ejércitos por un territorio', 'Este verbo describe la dispersión o esparcimiento de poblaciones y ejércitos. Génesis 9:19 declara que de los hijos de Noé «fue repartida toda la tierra», mientras que Isaías 33:3 describe a las naciones dispersándose ante el juicio divino. La raíz podría estar emparentada con el más común פוּץ (esparcir), aunque algunos especialistas la derivan como raíz independiente con cognados en arameo y árabe que significan sacudir, derramar o dispersar. El término abarca tanto la acción activa de dispersar como el estado resultante de estar esparcido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5312', 'spa', 'Salir, surgir (Qal intransitivo); sacar, hacer salir (Hifil causativo) — arameo', 'El verbo arameo נְפַק es el equivalente del hebreo יָצָא y significa ''salir'' o ''surgir''. Sus doce apariciones se encuentran en las secciones arameas de Daniel y Esdras. En su forma Qal (Pe''al), describe a personas saliendo de un lugar: Daniel ''salió'' hacia el verdugo del rey (Dan 2:14), los tres varones ''salieron'' del horno de fuego (Dan 3:26) y unos dedos fantasmales ''aparecieron'' para escribir en la pared (Dan 5:5). En su forma Hifil (Hafel) causativa, significa sacar algo, como cuando Ciro sacó los utensilios del templo (Esd 5:14; 6:5) y Belsasar mandó traerlos para su banquete (Dan 5:2–3).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5314', 'spa', 'Tomar aliento, reponerse; forma Nifal de נָפַשׁ, descansar y recobrar fuerzas', 'Este verbo denominativo, derivado del sustantivo נֶפֶשׁ (aliento, vida, alma), significa respirar hondo, tomar aliento o reponerse tras un esfuerzo. La Ley ordena descansar el séptimo día «para que reposen tu buey y tu asno, y se refresque el hijo de tu sierva» (Éxodo 23:12). Éxodo 31:17 emplea un llamativo antropomorfismo: Dios mismo «reposó» después de seis días de creación. Cuando David y sus hombres exhaustos llegan al Jordán huyendo de Absalón, se detienen a «reponerse» (2 Samuel 16:14). El verbo capta esa respiración profunda y restauradora que sigue al trabajo o la angustia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5315', 'spa', 'Alma, vida, ser, persona; el ser interior que respira — sede del deseo, la emoción y la existencia vital', 'Quizá el término antropológico más rico de la Biblia hebrea, נֶפֶשׁ abarca a la persona animada en su totalidad: desde el aliento de vida que Dios sopló en Adán (Gn 2:7) hasta el grito desesperado ''mi alma tiene sed de Dios'' (Sal 42:2). Resiste una traducción unívoca: el coreano lo divide entre 영혼 (''alma'') y 생명 (''vida''), el suajili entre nafsi (''yo interior'') y uhai (''vitalidad''), y el español entre alma y vida. En textos legales significa simplemente ''persona'', una cabeza contable. En su raíz, נֶפֶשׁ es aquello que hace a una criatura viva, deseante y presente en el mundo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5317', 'spa', 'Miel virgen, miel que fluye del panal; usada figuradamente para palabras dulces o seductoras', 'Designa la miel en su forma más pura y atractiva: fresca, goteando directamente del panal sin procesar. Aparece en la literatura sapiencial como parámetro supremo de dulzura: los juicios de Dios son más dulces que nópheth (Sal 19:10) y el hombre saciado la desprecia (Pr 27:7). También funciona como imagen poderosa del habla peligrosamente seductora (Pr 5:3) y de los labios de la amada que destilan miel (Cnt 4:11). Su campo semántico abarca tanto la pureza literal del panal como la dulzura figurada del lenguaje.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5321', 'spa', 'Neftalí — el sexto hijo de Jacob (por Bilha), y la tribu israelita y el territorio que llevan su nombre.', 'Neftalí — el sexto hijo de Jacob (por Bilha), y la tribu israelita y el territorio que llevan su nombre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5322b', 'spa', 'Gavilán, ave de rapiña; término genérico que abarca halcones y gavilanes', 'Este sustantivo designa a la familia de los gavilanes, clasificados como aves impuras en Levítico 11:16 y Deuteronomio 14:15 (ambos añaden «según su especie», indicando múltiples variedades). Job 39:26 celebra la migración instintiva del gavilán: «¿Vuela el gavilán por tu sabiduría y extiende sus alas hacia el sur?». La referencia capta el vuelo estacional del ave desde Palestina hacia regiones más cálidas. Los naturalistas antiguos reconocían varias especies de rapaces bajo este término. El gavilán ejemplifica a las criaturas salvajes e indomables que obran por instinto divino, no por adiestramiento humano: se elevan fuera de nuestro control, pero dentro del designio de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5324', 'spa', 'Estar de pie, apostarse, tomar posición (Nifal); erigir, levantar, establecer (Hifil); como participio, un oficial o gobernador.', 'Estar de pie, apostarse, tomar posición (Nifal); erigir, levantar, establecer (Hifil); como participio, un oficial o gobernador.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5327a', 'spa', 'Luchar, contender, reñir; conflicto físico o verbal entre partes.', 'Verbo que denota lucha física o contienda entre partes opuestas, tanto en Nifal (lucha recíproca) como en Hifil (enfrentarse contra alguien). Su uso más temprano describe a Moisés presenciando la riña de dos hebreos (Éx 2:13), y rige casuística legal clave: la ley sobre lesiones a una mujer embarazada durante una pelea (Éx 21:22) y la regulación de Deuteronomio 25:11. Las traducciones en diversas lenguas — español «contendieron», francés «combattant», alemán «fighting» — apuntan de manera consistente a una altercación física más que a una mera disputa verbal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5327b', 'spa', 'Caer en ruinas, quedar destruido; se usa para ciudades arrasadas', 'Este verbo describe ciudades que caen en montones de escombros. Jeremías advierte que las ciudades de Judá «serán destruidas, sin morador» (Jeremías 4:7). Los relatos paralelos de 2 Reyes 19:25 e Isaías 37:26 emplean el participio Nifal «montones de ruinas» para describir ciudades fortificadas reducidas a escombros por la conquista asiria, cumpliendo el antiguo propósito de Dios. La imagen es de muros que se desploman en pilas de piedra, moradas convertidas en desolación. El verbo transmite no un simple abandono, sino la reducción violenta a escombros: lo opuesto a la fortificación y la habitación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5329', 'spa', 'Director de coro o director musical (participio Piel); supervisar o dirigir trabajos (Piel); duradero, perpetuo (participio Nifal).', 'Director de coro o director musical (participio Piel); supervisar o dirigir trabajos (Piel); duradero, perpetuo (participio Nifal).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5331', 'spa', 'Perpetuidad, para siempre; eminencia, gloria; resistencia; victoria — una palabra que abarca tiempo, majestad y triunfo.', 'Perpetuidad, para siempre; eminencia, gloria; resistencia; victoria — una palabra que abarca tiempo, majestad y triunfo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5333', 'spa', 'Guarnición, puesto militar; también gobernador o funcionario designado; raramente, columna o pilar erguido.', 'Netsiv abarca los ámbitos militar, administrativo y monumental. Con mayor frecuencia designa una guarnición o puesto militar: las instalaciones filisteas que provocaron el audaz ataque de Jonatán (1 Sam 13:3-4) y las guarniciones que David estableció en Edom y Aram (2 Sam 8:6, 14). La misma raíz produce el sentido de gobernador o intendente designado, como los prefectos administrativos de Salomón (1 Re 4:19; 2 Cr 8:10). En una memorable aparición, describe la columna de sal en que se convirtió la mujer de Lot (Gn 19:26), un monumento erigido como testimonio del juicio divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5337', 'spa', 'Librar, rescatar, arrebatar; Nifal: escapar, ser librado; Piel: despojar, saquear; Hifil: salvar del peligro o del enemigo.', 'En su uso nuclear Hifil, נצל es el verbo de rescate por excelencia de la Biblia hebrea — Dios arrancando a Israel de la mano de Egipto, un pastor sacando un cordero de las fauces del león, un guerrero librando al oprimido. El árabe descompone el campo semántico con nitidez: أنجد para rescatar, انتزع para arrebatar y سلب para saquear — tres raíces distintas que confirman fracturas semánticas reales. El Nifal reflexivo añade la idea de escapar y autoliberarse, mientras que el raro Piel transforma el verbo en su opuesto: despojar y saquear al vencido. Una aparición Hitpael extiende la raíz al acto de despojarse de los propios ornamentos en señal de duelo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5338', 'spa', 'Rescatar, librar; Hafel arameo de נְצַל, salvar de peligro mortal', 'Este verbo arameo significa rescatar o librar, y aparece en las secciones arameas de Daniel. Se describe a Dios como quien «rescata y libra» (Daniel 6:27), demostrando su poder para salvar tanto del horno como de los leones. El verbo aparece en diversas formas: participio («el que rescata»), infinitivo («para librar») y con sufijos pronominales («para rescatarlo»). Nabucodonosor decreta muerte para quien hable contra el Dios «que puede librar de esta manera» (3:29), reconociendo que ningún otro dios puede rescatar como lo hace el Dios de Israel. El contexto arameo encaja con la situación del exilio, donde la liberación es una necesidad urgente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5341', 'spa', 'Vigilar, guardar, custodiar; referido a observar mandamientos, proteger personas, montar guardia y sitiar ciudades.', 'Vigilar, guardar, custodiar; referido a observar mandamientos, proteger personas, montar guardia y sitiar ciudades.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5342', 'spa', 'brote, retoño, vástago; usado figuradamente para referirse a descendencia o nuevo crecimiento desde una raíz', 'Este sustantivo designa un brote o rama joven que surge de una planta, pero en las Escrituras aparece exclusivamente en contextos figurados. Isaías 11:1 profetiza célebremente que «saldrá un vástago del tronco de Isaí», en referencia al Mesías. Isaías 60:21 llama a Israel «el retoño de mi plantío», mientras que Isaías 14:19 lo emplea en oráculos de juicio. El término transmite la idea de vida nueva que brota de raíces establecidas, frecuentemente con connotaciones mesiánicas o de pacto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5344a', 'spa', 'Perforar o traspasar; designar o especificar por nombre; maldecir o blasfemar, especialmente el Nombre divino.', 'Perforar o traspasar; designar o especificar por nombre; maldecir o blasfemar, especialmente el Nombre divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5347', 'spa', 'Hembra — mujer o animal hembra, usado para la distinción de sexo especialmente en textos sacerdotales y de la creación.', 'Hembra — mujer o animal hembra, usado para la distinción de sexo especialmente en textos sacerdotales y de la creación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5348', 'spa', 'Moteado, con pequeñas manchas; se usa exclusivamente de ovejas y cabras en el acuerdo de Jacob con Labán.', 'Este adjetivo describe animales que presentan pequeñas motas o salpicaduras en su pelaje, y aparece únicamente en la narración de Jacob y Labán en Génesis 30-31. Cuando Jacob negocia su salario, reclama como suyas todas las reses moteadas (נָקֹד) y manchadas (טָלוּא) (Gn 30:32-33). El término reaparece conforme los rebaños de Jacob se multiplican mediante su estrategia de cría selectiva (30:35, 39; 31:8, 10, 12). La palabra siempre aparece junto a términos afines de patrones de color — ''listado'' (עָקֹד) y ''manchado'' (טָלוּא) — formando un pequeño vocabulario técnico para las marcas del ganado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5350', 'spa', 'migajas, pan desmenuzado; o galletas duras/tortas secas', 'Este sustantivo plural tiene dos posibles significados, ambos relacionados con el pan. En Josué 9:5, 12, describe el pan de los gabaonitas que «estaba seco y se había desmenuzado», ya sea desmoronado por el tiempo (probando que venían de lejos) o quizás mohoso. En 1 Reyes 14:3, aparece entre provisiones llevadas como regalo junto con pan y miel, indicando más bien un tipo específico de producto horneado (tortas o galletas) que migajas literales. La ambigüedad refleja nuestro conocimiento limitado de los productos horneados del antiguo Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5352', 'spa', 'Estar limpio, ser inocente; Nifal: quedar impune, ser absuelto, quedar libre de obligación; Piel: absolver, dejar impune, limpiar de culpa.', 'Estar limpio, ser inocente; Nifal: quedar impune, ser absuelto, quedar libre de obligación; Piel: absolver, dejar impune, limpiar de culpa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5353', 'spa', 'Necodá; cabeza de familia de los netineos (sirvientes del templo) que regresaron del exilio babilónico', 'Necodá aparece como nombre de un líder entre los netineos, los sirvientes del templo que regresaron a Jerusalén tras el exilio en Babilonia. El nombre figura en las listas paralelas de Esdras 2:48, 60 y Nehemías 7:50, 62, lo que indica tanto un grupo familiar como posiblemente individuos que portaban este nombre. Las versiones griegas lo transcriben como Νεκωθα o Νεχωδα.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5355a', 'spa', 'Inocente, sin culpa; libre de culpa, obligación o deber; limpio y puro de manos o conciencia.', 'Inocente, sin culpa; libre de culpa, obligación o deber; limpio y puro de manos o conciencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5356a', 'spa', 'Inocencia, limpieza moral; ausencia de culpa, especialmente en la expresión «inocencia de manos»', 'Este sustantivo describe la inocencia moral o la ausencia de culpa, con mayor frecuencia en la expresión «inocencia de manos» (נִקְּיוֹן כַּפַּיִם), que simboliza una conducta íntegra y sin reproche. En Génesis 20:5, Abimelec la invoca como defensa ante Dios, mientras que los Salmos 26:6 y 73:13 la emplean en contextos de pureza ritual y vida recta. Oseas 8:5 la extiende al sentido de exención de castigo, y Amós 4:6 juega con su sentido literal de limpieza física («limpieza de dientes» = hambruna, ausencia de alimento).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5357', 'spa', 'hendidura de roca, grieta rocosa; abertura estrecha en formaciones de piedra', 'Este sustantivo designa hendiduras o grietas estrechas en paredes de roca, el tipo de espacios angostos donde uno puede esconderse o donde anidan criaturas. Isaías 7:19 advierte que las fuerzas de Egipto y Asiria se asentarán «en todas las hendiduras de las rocas» de Judá: todo escondite albergará enemigos. Jeremías debe ocultar su cinto de lino «en una hendidura de la roca» junto al Éufrates como señal profética (13:4), y más adelante habla de pescadores que sacan personas «de cada grieta de las rocas» (16:16). La imagen sugiere vulnerabilidad: ni las posiciones más secretas ofrecen escape del juicio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5358', 'spa', 'Vengar, tomar venganza; en Nifal, vengarse a sí mismo; como participio, vengador; en Piel, ejecutar venganza plena.', 'Vengar, tomar venganza; en Nifal, vengarse a sí mismo; como participio, vengador; en Piel, ejecutar venganza plena.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5359', 'spa', 'Venganza, retribución — el acto de castigar las ofensas, especialmente el castigo judicial decisivo de Dios contra los que quebrantan el pacto y los o', 'Venganza, retribución — el acto de castigar las ofensas, especialmente el castigo judicial decisivo de Dios contra los que quebrantan el pacto y los opresores');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5360', 'spa', 'Venganza, retribución — el acto de retribución divina o humana por el agravio, especialmente en contextos de justicia pactual.', 'Venganza, retribución — el acto de retribución divina o humana por el agravio, especialmente en contextos de justicia pactual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5361', 'spa', 'ser separado, enajenado, apartado; ruptura emocional y relacional', 'Este verbo expresa ser separado o enajenado, y se usa exclusivamente en la alegoría de Oholá y Oholibá en Ezequiel (Jerusalén y Samaria personificadas como hermanas infieles). Tres veces Dios declara «mi alma se apartó de ella» (Ezequiel 23:18, 22, 28), empleando el mismo lenguaje de extrañamiento profundo. La raíz sugiere separación violenta o ruptura, emparentada con palabras que significan «rasgar» o «hender». La forma qal perfecta con «mi alma» como sujeto crea un lenguaje teológico impactante: el ser mismo de Dios se retrae del socio del pacto que se ha vuelto repulsivo por su infidelidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5362b', 'spa', 'Rodear, circundar, cercar; recorrer en circuito, cerrar el cerco con hostilidad, o completar un ciclo de tiempo', 'Rodear, circundar, cercar; recorrer en circuito, cerrar el cerco con hostilidad, o completar un ciclo de tiempo');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5365', 'spa', 'Horadar, arrancar o sacar; especialmente sacar los ojos, tambien perforar huesos o excavar piedra.', 'Verbo que significa horadar, arrancar o sacar con fuerza, dotado de una fisicidad visceral que lo convierte en uno de los terminos mas graficos de las Escrituras hebreas. Su aplicacion mas frecuente es el arrancamiento de ojos: Najas el amonita amenazo con sacar el ojo derecho a todo hombre de Jabes de Galaad (1 Sam 11:2), y los filisteos sacaron los ojos a Sanson tras su captura (Jue 16:21). Proverbios 30:17 advierte que los cuervos sacaran el ojo burlador. En Job 30:17 el termino se desplaza para describir huesos perforados por un dolor implacable. Isaias 51:1 usa el Pual pasivo para la cantera de la que Israel fue excavado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5367', 'spa', 'Atrapar, tender lazo, poner trampa; enredar o hacer caer a alguien mediante engaño', 'Originalmente con el sentido de ''golpear'' o ''abatir'' (cf. arameo נְקַשׁ, ''golpear''), este verbo se especializa en hebreo como figura de la caza con trampa: derribar a alguien como el cazador abate un ave con un palo lanzado. Aparece en advertencias contra el enredo idolátrico (Dt 12:30), en descripciones de enemigos que tienden lazos al salmista (Sal 38:12; 109:11) y en la irónica inversión donde los malvados caen en su propia red (Sal 9:16). La imagen dominante es la del cazador que deliberada y sigilosamente prepara la trampa para su presa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5369', 'spa', 'Ner — nombre propio que significa ''lámpara'', padre de Abner y ancestro benjaminita de Saúl', 'Ner — nombre propio que significa ''lámpara'', padre de Abner y ancestro benjaminita de Saúl');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5371', 'spa', 'Nergal-Saréser; oficial babilonio presente en la caída de Jerusalén, cuyo nombre significa «Nergal, protege al rey».', 'Nombre propio compuesto de origen acadio, llevado por un oficial babilonio del séquito de Nabucodonosor durante el asedio y caída de Jerusalén en el 586 a.C. El nombre combina al dios babilónico Nergal con la plegaria «protege al rey» (shar-usur). Aparece en Jeremías 39:3,13, donde figura entre los oficiales que entraron en Jerusalén tras la brecha de sus murallas y que posteriormente facilitaron la liberación de Jeremías de prisión por orden de Nabucodonosor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5372', 'spa', 'Murmurar, susurrar, calumniar; usado para la queja rebelde o el chisme malicioso', 'Este verbo abarca dos sentidos relacionados: murmurar con rebeldía (como Israel murmuró contra Dios en el desierto) y susurrar con malicia a modo de calumniador o chismoso. En Deuteronomio 1:27 y Salmo 106:25 describe la murmuración rebelde de los israelitas en sus tiendas. En Proverbios (16:28; 18:8; 26:20, 22), la forma participial designa al «chismoso» o calumniador que siembra discordia mediante un hablar secreto y malintencionado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5373', 'spa', 'nardo, planta aromática originaria de la India; usado como perfume y ungüento', 'Este sustantivo se refiere al nardo (o espicanardo), una planta aromática muy valorada importada desde la India a través de Persia. La amada en el Cantar de los Cantares dice «mientras el rey estaba a su mesa, mi nardo exhaló su fragancia» (1:12), evocando presencia íntima mediante un perfume costoso. El nardo aparece en el inventario de especias del jardín: «nardo y azafrán, cálamo y canela» (4:13-14). Su origen asiático lo convertía en un artículo de lujo en el mundo mediterráneo antiguo. Los lectores del Nuevo Testamento recordarán la unción de Jesús por María con nardo puro (Marcos 14:3), «muy costoso», la misma sustancia exótica celebrada aquí por su fragancia y rareza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5374', 'spa', 'Nerías (Neriyah/Neriyahu), padre de Baruc el escriba y de Seraías; judahita contemporáneo de Jeremías.', 'Nombre propio que significa ''lámpara de Yah'' o ''Yahveh es mi luz'', llevado por el padre de dos figuras importantes en el libro de Jeremías: Baruc el escriba (Jer 32:12; 36:4, 8, 32) y Seraías el oficial de intendencia (Jer 51:59). El nombre aparece tanto en su forma larga Neriyahu (con el sufijo teofórico -yahu; Jer 36:14, 32; 43:6; 45:1) como en la forma corta Neriyah (Jer 32:12, 16; 36:4, 8; 43:3). Baruc hijo de Nerías sirvió como fiel secretario de Jeremías, leyendo el rollo profético en público y preservando los oráculos del profeta para la posteridad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5375', 'spa', 'Levantar, cargar, llevar; tomar, recibir; perdonar pecado; alzar (ojos, voz, manos, cabeza); ser exaltado', 'Este verbo aparece 654 veces con un campo semántico notablemente amplio, anclado en el movimiento físico ascendente. Desde alzar los ojos al cielo (Gn 18:2) hasta cargar las varas del arca (Éx 25:14), desde levantar un censo (Éx 30:12) hasta perdonar la iniquidad (Gn 50:17), el hilo conductor es siempre el movimiento: hacia arriba, hacia afuera o hacia adentro. El Qal abarca la mayoría de los significados, el Piel intensifica (''sostener, exaltar''), el Nifal indica elevación pasiva y el Hitpael la autoexaltación reflexiva. El español distingue alzar, llevar y perdonar, mientras que el hebreo condensa todo en esta única raíz versátil.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5376', 'spa', 'levantar, tomar, llevar; verbo arameo para cargar o sublevarse', 'Este verbo arameo describe levantar, llevar o tomar. En el tronco básico (pe''al) aparece cuando el viento «se lleva» los reinos destrozados en la visión de Daniel (2:35) y cuando se ordena «tomar» los utensilios del templo para llevarlos a Jerusalén (Esdras 5:15). El tronco hitpael significa «levantarse en insurrección», describiendo una ciudad que «se subleva» en rebelión (Esdras 4:19). El rango semántico va desde el transporte físico hasta el alzamiento metafórico. El contexto arameo corresponde a los documentos del período persa en Esdras y la corte babilónica en Daniel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5377', 'spa', 'Engañar, seducir o desviar; principalmente en el tronco Hifil para engaño activo, con un pasivo Nifal y extensiones poco frecuentes', 'Engañar, seducir o desviar; principalmente en el tronco Hifil para engaño activo, con un pasivo Nifal y extensiones poco frecuentes');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5378', 'spa', 'Prestar con interés, actuar como acreedor; exigir pago o hacer demandas financieras', 'Este verbo, vinculado a las formas de נָשָׁה, describe la acción de prestar dinero con interés o desempeñar el papel de acreedor. En 1 Samuel 22:2 se refiere a «todo hombre que tenía acreedor», mientras que Isaías 24:2 coloca en paralelo al acreedor y al deudor. El Salmo 89:22 emplea la forma hifil para describir que el enemigo «no le impondrá tributo» al rey ungido. La raíz transmite la idea de obligación financiera y el derecho legal del acreedor a cobrar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5380', 'spa', 'soplar (del viento); hacer soplar o ahuyentar soplando', 'Este verbo describe la acción de soplar del viento o de hacer que algo sea soplado. En su forma Qal aparece en Isaías 40:7: «el aliento de YHWH sopla sobre ella», marchitando la hierba y secando las flores como imagen de la fragilidad humana. En la forma Hifil causativa, el Salmo 147:18 dice «hace soplar su viento» y el hielo se derrite en agua corriente. En Génesis 15:11, Abraham «ahuyentó» las aves de rapiña del sacrificio, quizás conservando un sentido antiguo de espantar soplando. El verbo capta el poder del aliento o el viento para producir cambio: marchitar, derretir o dispersar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5381', 'spa', 'Alcanzar, dar alcance, lograr; en persecución: dar alcance; de recursos: poder costear, bastar; de bendiciones: sobrevenir.', 'Alcanzar, dar alcance, lograr; en persecución: dar alcance; de recursos: poder costear, bastar; de bendiciones: sobrevenir.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5382', 'spa', 'Olvidar o ser olvidado; en forma causativa, hacer que alguien olvide: abarca el duelo personal, el juicio divino y el alivio providencial del dolor.', 'Verbo cuyas dos formas verbales trazan el arco completo del olvido. En Qal y Nifal, el sujeto simplemente olvida: el hablante de Jeremias dice que ha olvidado la prosperidad (Lam 3:17), y Dios advierte que olvidara a su pueblo (Jer 23:39), mientras que Isaias asegura a Israel que no sera olvidado (Isa 44:21). En Piel e Hifil, alguien es hecho olvidar: Jose nombra a su hijo Manases porque Dios le hizo olvidar toda su afliccion (Gen 41:51), y los amigos de Job sugieren que Dios hace olvidar parte de la culpa (Job 11:6). La distincion causativa del hebreo se refleja con precision en el espanol mediante la perifrasis hacer olvidar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5383', 'spa', 'Prestar dinero o bienes; como participio, acreedor o usurero; en Hifil, conceder un préstamo o exigir una deuda', 'Este verbo rige el mundo económico del préstamo, el endeudamiento y el cobro de deudas en el antiguo Israel. En su forma Qal significa simplemente ''prestar'', como en Jeremías 15:10 donde el profeta protesta que no ha prestado ni le han prestado. El participio se convierte en sustantivo con el sentido de ''acreedor'', la figura detrás del clamor de la viuda en 2 Reyes 4:1 y la inversión social de Isaías 24:2. La preocupación de la Torá por el préstamo justo (Éx 22:25, Dt 15:2) hace de esta palabra una ventana a la ética económica bíblica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5387a', 'spa', 'Jefe, príncipe o líder tribal; persona elevada a la autoridad sobre un clan, una tribu o una nación.', 'En el Pentateuco y en Crónicas, este sustantivo designa a los jefes reconocidos de las doce tribus de Israel: los líderes convocados por Moisés e inscritos en los censos de Números. La raíz נ-שׂ-א (''elevar, alzar'') captura la idea de alguien elevado por encima de sus parientes. El alemán emplea Führer (''líder'') para los jefes tribales, pero cambia a Fürst (''príncipe'') para la figura soberana en Ezequiel, reflejando cómo la palabra se extiende desde un cabecilla comunitario hasta el príncipe-pastor escatológico de Ezequiel 34-48.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5387b', 'spa', 'Nubes, vapores; neblina ascendente que forma nubes y presagia lluvia', 'Este sustantivo, distinto del más frecuente נָשִׂיא (príncipe, jefe), se refiere a los vapores atmosféricos o nubes, especialmente aquellas que se elevan y traen lluvia. Jeremías 10:13 y 51:16 describen a Dios haciendo subir «nubes desde los confines de la tierra», mientras que Salmo 135:7 y Proverbios 25:14 emplean el término en contextos que asocian las nubes con la lluvia o con su ausencia. La raíz sugiere algo «elevado» o «que asciende», en consonancia con la imagen de vapores que suben.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5391a', 'spa', 'Morder, especialmente dicho de serpientes; intensivo, infligir mordeduras repetidas; metafóricamente, cobrar interés usurario.', 'נָשַׁךְ (nashakh) es ante todo la mordedura de la serpiente, el peligro primordial que recorre desde Génesis hasta Eclesiastés. El oráculo de Jacob presenta a Dan como una víbora que ''muerde'' los talones del caballo (Gn 49:17), y el episodio de la serpiente de bronce gira en torno a esta palabra tanto para el que muerde como para el mordido (Nm 21:8-9). El Piel intensifica la imagen en un ataque mortífero y repetido, como cuando las serpientes ardientes ''mordieron'' al pueblo en el desierto (Nm 21:6). Lo más llamativo es el salto metafórico en Habacuc 2:7: los acreedores que ''muerden'' a sus deudores mediante la usura, el depredador financiero como serpiente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5391b', 'spa', 'cobrar intereses, prestar con usura; hacer que alguien pague intereses sobre un préstamo', 'Este verbo denominativo, derivado de נֶשֶׁךְ (interés, usura), significa prestar dinero a interés o cobrar usura. Aparece exclusivamente en Deuteronomio 23:19-20, donde la ley permite cobrar intereses a los extranjeros pero lo prohíbe entre israelitas. El Qal significa «dar interés», mientras que el Hifil significa «hacer pagar interés» o «cobrar interés». Esto refleja la ética económica del antiguo Cercano Oriente respecto a los préstamos dentro de la comunidad del pacto frente a los forasteros.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5392', 'spa', 'Interés, usura — interés cobrado sobre préstamos de dinero o bienes, condenado en la ley bíblica como explotador.', 'El sustantivo נֶשֶׁךְ (neshek) designa el interés cobrado sobre un préstamo, derivado del verbo nashakh (''morder''), evocando la garra consumidora del acreedor. La ley bíblica prohíbe cobrar interés a los connacionales israelitas: ''No le cobrarás interés'' (Ex 22:25; Lv 25:36-37; Dt 23:19). Ezequiel incluye el cobro de intereses entre los pecados que condenan a una persona (Ez 18:8, 13, 17; 22:12), y el Salmo 15:5 cuenta la negativa a prestar con interés como marca del justo. Proverbios 28:8 lo empareja con tarbit (''ganancia'') para describir el préstamo explotador.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5393', 'spa', 'cámara, almacén; término arquitectónico para aposentos de almacenamiento o residencia', 'Este sustantivo designa una cámara o aposento, especialmente destinado al almacenamiento o la habitación individual. Funciona como un paralelo menos frecuente del término más común לִשְׁכָּה (cámara). En Nehemías 3:30, alguien hace reparaciones «frente a su cámara», indicando aposentos residenciales personales. Nehemías 13:7 se refiere a la cámara que Eliasib había preparado para Tobías en los atrios del templo, un uso escandaloso del espacio sagrado. El plural en Nehemías 12:44 designa «almacenes» para los diezmos y las ofrendas. El término abarca desde habitaciones privadas hasta depósitos sagrados, siempre sugiriendo recintos dentro de un complejo mayor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5394', 'spa', 'Deslizar, soltar; quitar (sandalias); expulsar, desposeer (naciones).', 'Verbo versátil cuyos sentidos abarcan desde lo cotidiano hasta lo trascendental. En su uso más físico, la cabeza de un hacha «se suelta» de su mango (Dt 19:5) y las aceitunas «se caen» prematuramente (Dt 28:40). La misma raíz ordena a Moisés y Josué «quitarse» las sandalias en tierra santa (Éx 3:5; Jos 5:15), un acto deliberado y no accidental. En su sentido más dramático, Dios «expulsa» naciones ante Israel (Dt 7:1, 22), donde la metáfora de arrancar se extiende al despojo de pueblos de su tierra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5397', 'spa', 'Aliento — desde el soplo vivificante de Dios, hasta su ráfaga de ira, hasta el ser viviente que respira.', 'Aliento — desde el soplo vivificante de Dios, hasta su ráfaga de ira, hasta el ser viviente que respira.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5399', 'spa', 'Crepúsculo — la luz tenue de transición al atardecer (ocaso) o al amanecer (alba)', 'El sustantivo נֶשֶׁף designa la luz suave e incierta del crepúsculo, ese momento liminal en que el día cede ante la noche o viceversa. Generalmente se refiere al ocaso, hora preferida por quienes buscan ocultarse: el adúltero acecha el crepúsculo (Job 24:15) y la mujer disoluta merodea al anochecer (Pr 7:9). El ejército arameo huyó al crepúsculo (2 R 7:5, 7). En dos pasajes apunta al alba: el insomne espera un amanecer que no llega (Job 7:4) y el salmista se levanta antes del alba para clamar (Sal 119:147). La ambigüedad entre tarde y mañana es inherente a la palabra, que nombra la penumbra más que una hora fija.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5400', 'spa', 'encender, quemar; prender fuego o hacer arder', 'Este verbo significa encender o quemar, y aparece tanto en la forma pasiva (Nifal: ser encendido) como en la causativa (Hifil: hacer arder). El Salmo 78:21 describe la ira de Dios: «un fuego se encendió contra Jacob», la indignación divina que arde como llama. Isaías 44:15 habla de quien toma parte de un árbol y «enciende fuego» para calentarse, en contraste con tallar el resto para hacer un ídolo. Ezequiel 39:9 profetiza que Israel «encenderá fuego» con las armas del derrotado Gog, siete años de combustible a partir de instrumentos de guerra. El verbo abarca tanto la combustión espontánea de la ira como el acto deliberado de prender fuego.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5401a', 'spa', 'Besar (saludo, despedida, homenaje); en Hifil, de objetos que se tocan o hacen contacto.', 'Besar (saludo, despedida, homenaje); en Hifil, de objetos que se tocan o hacen contacto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5401b', 'spa', 'equipado con, portador de; que lleva o empuña armas (especialmente arcos)', 'Esta forma participial significa «equipado con» o «portador de», y describe específicamente a guerreros que portan armas determinadas. En 1 Crónicas 12:2, los benjaminitas que se unieron a David son llamados «equipados con arco», arqueros diestros. El Salmo 78:9 habla de «los efrateos, armados de arco», que sin embargo «retrocedieron el día de la batalla», un fracaso militar pese al equipamiento adecuado. 2 Crónicas 17:17 enumera un comandante con soldados «armados de arco y escudo». El matiz exacto se debate: ya sea «equipado con» (portar como pertrechos) o «diestro en el manejo de» (usuario entrenado). En cualquier caso, denota preparación militar con armamento específico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5402', 'spa', 'Armas, armamento, equipo militar (colectivo); también arsenal o armería como lugar de almacenamiento de armas', 'Sustantivo masculino usado colectivamente para designar armas y equipo militar. Aparece en contextos que van desde el tributo real (1 R 10:25, armas llevadas a Salomón) hasta el juicio profético (Ez 39:9-10, la quema de las armas de Gog). Job 20:24 especifica «armas de hierro» junto a un «arco de bronce», mientras que el Salmo 140:8 habla del «día de las armas», es decir, el día de la batalla. En un caso (Neh 3:19), la palabra no designa las armas en sí, sino el lugar donde se almacenan —la armería—, usado como punto de referencia durante la reconstrucción del muro de Jerusalén.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5404', 'spa', 'Águila o buitre leonado — gran rapaz que simboliza velocidad, poder, cuidado divino y majestad en las Escrituras.', 'Águila o buitre leonado — gran rapaz que simboliza velocidad, poder, cuidado divino y majestad en las Escrituras.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5405', 'spa', 'secarse, resecarse; agotarse por falta de humedad o vitalidad', 'Este verbo describe el estado de estar completamente seco o reseco. Isaías 41:17 retrata a los pobres desesperados cuya «lengua desfallece de sed», una deshidratación extrema como metáfora de la necesidad espiritual. Isaías 19:5 advierte que «las aguas del mar se agotarán», el Nilo que falla y la fuente vital de Egipto que se evapora. Jeremías 51:30 lo emplea metafóricamente: los guerreros de Babilonia descubren que «su fuerza se ha agotado», el coraje y el vigor que se evaporan ante el enemigo. La forma Nifal enfatiza el estado pasivo de estar reseco, ya sea físicamente (agua, lengua) o en sentido figurado (la fuerza que falla como humedad que se disipa).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5407', 'spa', 'carta, documento escrito; correspondencia oficial en arameo', 'Este sustantivo arameo significa ''carta'' o documento escrito, probablemente tomado del persa (reflejando el contexto imperial persa de Esdras). Las tres apariciones se encuentran en la correspondencia aramea entre Jerusalén y la corte persa. Esdras 4:18 menciona ''la carta'' enviada al rey Artajerjes y leída ante él. Esdras 4:23 describe la acción tomada tras leer ''la copia de la carta del rey Artajerjes''. Esdras 5:5 se refiere a ''una carta'' sobre la reconstrucción del templo enviada al rey Darío. Estos documentos oficiales determinaron el destino de Jerusalén: permisos concedidos o denegados, obras autorizadas o detenidas, todo mediante cartas imperiales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5408', 'spa', 'Cortar en pedazos, descuartizar por las coyunturas (solo Piel); usado para el despiece sacrificial y el envío de partes como convocatoria.', 'Este verbo, que aparece exclusivamente en la forma intensiva Piel, describe el acto deliberado de cortar un cuerpo en piezas siguiendo sus articulaciones. Predominan dos contextos. En la legislación sacrificial, se refiere al despiece correcto de los holocaustos: el oferente desollaba y cortaba el animal en sus porciones antes de colocarlo sobre el altar (Lv 1:6, 12; 8:20; Éx 29:17; 1 R 18:23, 33). En la narrativa, describe el acto impactante de descuartizar un cuerpo y enviar las piezas por todo Israel como llamado a las armas: la concubina del levita (Jue 19:29; 20:6) y los bueyes de Saúl (1 S 11:7). El hebreo implica específicamente dividir por las coyunturas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5409', 'spa', 'Trozo, porción de un animal descuartizado; usado para los cortes sacrificiales y el desmembramiento simbólico', 'El sustantivo nétaj designa un trozo o porción cortada de un animal descuartizado, resultado de la acción expresada por su verbo cognado nataj (H5408, ''cortar en pedazos''). En el sistema sacrificial, la palabra describe las porciones en que se dividía el holocausto antes de disponerlas sobre el altar (Lv 1:6, 8, 12; Éx 29:17). La alegoría del caldero de Ezequiel emplea el término para los pedazos de carne que simbolizan a los habitantes de Jerusalén destinados al juicio (Ez 24:4–6). Más perturbadoramente, describe el desmembramiento de la concubina del levita en Jueces 19:29, un acto funesto destinado a convocar a Israel contra la maldad de Gabaa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5410a', 'spa', 'Senda, camino o sendero; ruta o curso de viaje, frecuentemente figurativo para la direccion moral o espiritual de la vida.', 'Sustantivo masculino que designa una senda, camino o sendero, usado predominantemente en la literatura sapiencial y poetica. A diferencia del mas comun derek (camino), nativ suele portar un registro elevado y literario. En Job describe sendas ocultas: la senda encubierta por una trampa (18:10), la senda que ninguna ave de rapina ha visto (28:7) y el rastro luminoso que deja Leviatan (41:32). El salmista pide ser guiado por la senda de los mandamientos divinos (Sal 119:35), mientras que el Salmo 78:50 habla de Dios allanando una senda para su ira. Proverbios 12:28 lo emplea para la senda de justicia que conduce a la vida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5410b', 'spa', 'Senda o vereda; en sentido figurado, un curso de vida o conducta moral', 'Senda o vereda; en sentido figurado, un curso de vida o conducta moral');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5411', 'spa', 'Netineos: sirvientes del templo ''dados'' para asistir a los levitas en las labores del santuario, prominentes en textos postexílicos', 'Netineos: sirvientes del templo ''dados'' para asistir a los levitas en las labores del santuario, prominentes en textos postexílicos');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5413', 'spa', 'Derramar o ser derramado; referido a metales, fundir o refinar en un horno; en Hifil, causar el derramamiento o la fundición', 'Derramar o ser derramado; referido a metales, fundir o refinar en un horno; en Hifil, causar el derramamiento o la fundición');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5414', 'spa', 'Dar, poner, colocar, hacer, entregar; el verbo hebreo primario para transferir posesión o situar algo', 'Uno de los verbos más versátiles de la Biblia hebrea, נָתַן aparece más de 2.000 veces con un campo semántico que se extiende desde el simple dar hasta el nombramiento divino. En su núcleo describe la transferencia de algo entre partes: un regalo, una esposa, una tierra, un pacto. Pero también abarca colocar, designar y entregar, revelando cómo el hebreo antiguo concebía el ''dar'' como algo ampliamente relacional: Dios da la tierra, pone el arco iris, hace de Abraham padre de naciones y entrega a los enemigos en manos de Israel, todo con la misma raíz.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5415', 'spa', 'Dar, otorgar, conceder (arameo); entregar, pagar o conferir autoridad, usado en el arameo bíblico de Daniel y Esdras.', 'Cognado arameo del hebreo natan, que significa «dar, otorgar o conceder». Se encuentra exclusivamente en las secciones arameas de Daniel y Esdras, y abarca toda la gama del acto de dar: la concesión divina de soberanía (Dn 4:17,25,32 — Dios «da» el dominio a quien él quiere), la solicitud de tiempo (Dn 2:16), y el pago de tributo (Esd 4:13; 7:20). Su registro es formal y administrativo, propio del lenguaje de la corte y los decretos imperiales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5416', 'spa', 'Natán — nombre propio que significa ''él dio,'' portado por el profeta que confrontó a David y otros.', 'Natán — nombre propio que significa ''él dio,'' portado por el profeta que confrontó a David y otros.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5417', 'spa', 'Natanael; nombre propio teofórico que significa ''Dios ha dado'', portado por múltiples líderes israelitas', 'Un nombre teofórico compuesto formado por natán (''dar'') y ''El (''Dios''), Natanael significa ''Dios ha dado'', equivalente hebreo del Natanael griego del Nuevo Testamento. Lo llevan al menos diez individuos distintos que abarcan desde el período del desierto hasta la era postexílica. Su portador más destacado es el jefe de Isacar, que aparece cinco veces en Números (1:8; 2:5; 7:18, 23; 10:15), presentando la ofrenda de dedicación de su tribu. Otros incluyen un músico levita en la procesión de David (1 Cr 15:24), un portero entre los hijos de Obed-edom (1 Cr 26:4), un príncipe enviado por Josafat a enseñar en las ciudades de Judá (2 Cr 17:7) y un sacerdote en tiempos de Nehemías (Neh 12:21, 36).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5418', 'spa', 'Netanías o Netanyahu, nombre propio que significa ''Yahvé ha dado'', llevado por varios hombres en la Biblia hebrea', 'Netanías o Netanyahu, nombre propio que significa ''Yahvé ha dado'', llevado por varios hombres en la Biblia hebrea');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5422', 'spa', 'Derribar, demoler, destruir; de altares, muros, lugares altos; metafóricamente, quebrantar o destrozar a una persona.', 'Derribar, demoler, destruir; de altares, muros, lugares altos; metafóricamente, quebrantar o destrozar a una persona.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5423', 'spa', 'Tirar, arrancar o apartar; romper o quebrar ataduras; en voz pasiva, ser arrancado, quebrado o desarraigado.', 'Tirar, arrancar o apartar; romper o quebrar ataduras; en voz pasiva, ser arrancado, quebrado o desarraigado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5424', 'spa', 'Tiña, erupción cutánea; enfermedad eruptiva del cuero cabelludo o la barba examinada por sacerdotes según la ley de pureza', 'Un término médico-legal especializado confinado enteramente al código de pureza levítico en Levítico 13–14. Derivado de la raíz nataq (''arrancar, desprender''), néteq sugiere literalmente algo que uno tiende a rascar o arrancar, comparable al latín scabies de scabere (''rascar''). La afección aparece en la cabeza o la barba y requiere una inspección sacerdotal cuidadosa durante dos períodos de cuarentena de siete días: el sacerdote busca profundidad, propagación y la reveladora ausencia de pelo fino amarillento (Lv 13:30–37). Si sana y crece pelo negro, la persona es declarada limpia. El término se sitúa en la categoría más amplia de las afecciones sospechosas de tsará''at.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5425a', 'spa', 'saltar, brincar; movimiento súbito hacia arriba o estremecimiento', 'Este verbo describe un movimiento ascendente repentino: saltar, sobresaltarse o brincar. En Job 37:1 su corazón ''salta de su lugar'' como reacción involuntaria y violenta ante el trueno. Levítico 11:21 permite comer langostas que tienen patas ''para saltar sobre la tierra'', definiendo a los insectos puros por su forma de locomoción. Habacuc 3:6 retrata la teofanía divina: Dios ''miró e hizo temblar a las naciones'', literalmente las hizo sobresaltarse de terror. El hilo común es el movimiento súbito y convulsivo: corazones que brincan de alarma, langostas que saltan y naciones que se estremecen ante la presencia divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5425b', 'spa', 'Desatar, soltar, poner en libertad; liberar ataduras o prisioneros', 'Verbo en Hiphil que significa soltar lo que está atado, ya sean grilletes físicos, correas de yugo o una persona cautiva. Isaías 58:6 lo empareja con ''romper todo yugo'' en el gran oráculo del día de ayuno, exigiendo desatar las ligaduras de maldad. El salmista celebra a Dios como quien ''pone en libertad a los prisioneros'' (Sal 146:7) y quien envió orden de soltar a José de sus cadenas (Sal 105:20). Job 6:9 lo emplea figuradamente: ''que soltara su mano y acabara conmigo''. La fuerza semántica central es la de liberar rompiendo o aflojando lo que oprime.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5428', 'spa', 'Arrancar de raíz; en troncos pasivos, ser desarraigado o arrancado', 'Arrancar de raíz; en troncos pasivos, ser desarraigado o arrancado');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5429', 'spa', 'Sea, medida hebrea de áridos equivalente a un tercio de efa (aprox. 7 litros), usada para grano y harina.', 'La sea era una unidad estándar de medida de áridos en el antiguo Israel, equivalente a aproximadamente un tercio de efa o unos 7,3 litros. Abraham pide a Sara que prepare tres seas de harina fina para sus visitantes celestiales (Gn 18:6), Abigail lleva cinco seas de grano tostado a David (1 S 25:18), y Elías usa dos seas de semilla para medir la zanja alrededor de su altar en el monte Carmelo (1 R 18:32). Durante el sitio de Samaria, el cumplimiento milagroso de la profecía de Eliseo se mide en seas: ''una sea de harina fina por un siclo'' (2 R 7:1, 16, 18). La dificultad de traducir el vocabulario metrológico antiguo hace que muchas lenguas simplemente tomen prestado el término.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5433a', 'spa', 'beber en exceso, embriagarse; consumo desmedido de vino o bebida fuerte; borracho', 'Este verbo describe el acto de beber en exceso o el estado de embriaguez, y su participio funciona como sustantivo con el sentido de «borracho» o «bebedor». Deuteronomio 21:20 y Proverbios 23:21 condenan al «glotón y borracho» (זוֹלֵל וְסֹבֵא), mientras que Proverbios 23:20 advierte contra juntarse con «bebedores de vino». Isaías 56:12 usa la forma cohortativa en boca de los impíos: «embriaguémonos», y Nahúm 1:10 describe a los malhechores como «embriagados con su propia bebida» mediante un participio pasivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5434', 'spa', 'Seba; hijo de Cus y nación o territorio en el sur de Arabia o noreste de África', 'Seba aparece tanto como nombre personal (el primogénito de Cus en Génesis 10:7 y 1 Crónicas 1:9) como designación geográfica de una nación o región. El Salmo 72:10 vincula a Seba con Sabá en el tributo presentado al rey, mientras que Isaías 43:3 lo sitúa junto a Cus y Egipto como rescate por Israel. La mayoría de los estudiosos ubican a Seba en la costa occidental del mar Rojo, posiblemente el puerto de Saba en el golfo de Adúlis, distinto de la más conocida Sabá en Arabia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5435', 'spa', 'bebida, licor; bebida fuerte o selecta, a veces referido a la embriaguez misma', 'Este sustantivo designa una bebida o licor, especialmente bebidas fuertes o embriagantes. Isaías 1:22 lo emplea en una metáfora de corrupción: «tu bebida mezclada con agua», simbolizando una justicia adulterada. El texto de Oseas 4:18 es incierto: algunos leen «su licor (embriaguez) se acabó» y otros proponen enmiendas. Nahúm 1:10 puede referirse tanto a los borrachos como a su bebida. El término se solapa semánticamente con el verbo סָבָא (beber en exceso) y puede denotar tanto la bebida como el estado de embriaguez.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5437', 'spa', 'Girar, rodear, recorrer; (Qal) volverse, circundar; (Nifal) torcerse; (Hifil) hacer girar, desviar; (Hofal) ser vuelto.', 'El verbo hebreo סָבַב expresa movimiento circular o rotacional: girar, rodear y recorrer. En Qal describe tanto el giro intransitivo (cambiar de dirección) como el cercar transitivo (rodear un objeto). El Hifil añade fuerza causativa: hacer girar algo, conducir a alguien alrededor o trasladar objetos. Nifal y Hofal aportan las voces media y pasiva. El Piel intensifica la acción: circunvalar repetidamente o rodear con solemnidad. El centro semántico del verbo es el movimiento circular, ya sea literal (marchar alrededor de Jericó) o metafórico (transformar el corazón).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5439', 'spa', 'Alrededor, en derredor; como sustantivo, los alrededores o los pueblos circundantes.', 'Una de las palabras espacialmente más expresivas del hebreo, סָבִיב evoca un cuadro de cerco completo: ya sea un lindero que rodea un campo (Gn 23:17), una moldura que circunda el altar (Éx 25:11) o enemigos acampados por todos los costados (Sal 3:7). Funciona con flexibilidad como adverbio, preposición o sustantivo, y frecuentemente lleva sufijos pronominales: ''a su alrededor'', ''alrededor de ellos''. Cuando se usa como nombre, designa la región circundante o los pueblos vecinos, como en Salmo 44:13 donde Israel se vuelve oprobio ''para los que nos rodean''. La repetición סָבִיב סָבִיב (''una y otra vez'') en Eclesiastés 1:6 capta el circuito interminable del viento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5442', 'spa', 'matorral; vegetación densa y enmarañada en un bosque o espesura', 'Este sustantivo describe un matorral denso de arbustos o vegetación enmarañada. Génesis 22:13 relata el célebre episodio del carnero «trabado en un matorral por sus cuernos», que Abraham sacrificó en lugar de Isaac. Isaías emplea el término dos veces (9:17 y 10:34) para referirse a las «espesuras del bosque» que son consumidas por el fuego o taladas como acto de juicio. La imagen transmite impenetrabilidad y peligro, así como la dificultad de escapar una vez atrapado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5443', 'spa', 'trigón, lira triangular; instrumento musical de cuerdas (o posiblemente de viento) mencionado en Daniel', 'Este término designa un instrumento musical que aparece exclusivamente en Daniel 3 como parte de la orquesta real de Nabucodonosor. El nombre es probablemente un préstamo lingüístico emparentado con el griego σαμβύκη, un instrumento triangular de cuerdas con cuatro cuerdas. Algunos eruditos proponen que se trata de un arpa o lira, mientras que otros sugieren un tipo de gaita o instrumento de viento. El vocablo refleja la cultura cosmopolita de la corte babilónica y la influencia de la terminología musical helenística.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5444', 'spa', 'Sibecai; capitán y valiente guerrero de David, perteneciente a los husatitas', 'Sibecai fue uno de los guerreros de élite de David, un husatita que se distinguió en la batalla contra los filisteos. Mató a Saf (o Sipai), uno de los descendientes de los gigantes (2 Samuel 21:18, 1 Crónicas 20:4). También aparece en las listas de los valientes de David (1 Crónicas 11:29) y como comandante de una división en el sistema de milicias mensuales de David (1 Crónicas 27:11). Algunos manuscritos sugieren que su nombre en 2 Samuel 23:27 debería leerse Sibecai en lugar de Mebunai.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5445', 'spa', 'Cargar un peso, llevar cargas; en pasiva: estar cargado; en reflexivo: arrastrarse penosamente.', 'Un verbo de peso y resistencia que describe el acto de echar sobre los hombros lo que es pesado, ya sean sacos de grano o los dolores de una nación. Isacar inclina su hombro para cargar como un asno (Gn 49:15), y el Siervo Sufriente carga con nuestros dolores y lleva nuestras iniquidades (Is 53:4, 11). En su forma pasiva Pual describe ganado cargado de frutos (Sal 144:14), y en el raro Hitpael el saltamontes de Eclesiastés 12:5 se arrastra penosamente, imagen conmovedora de la vejez cuando hasta la criatura más ligera se convierte en carga para sí misma.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5447', 'spa', 'carga, peso; trabajo forzado o peso pesado que se debe llevar', 'Este sustantivo designa una carga o peso, ya sea literal (algo que se carga físicamente) o metafórico (opresión mediante trabajo forzado). En 1 Reyes 11:28 se describe a Jeroboam puesto sobre ''todo el trabajo forzado de la casa de José'', el sistema de corvea que acabaría dividiendo el reino. Nehemías 4:17 habla de los cargadores debilitados durante la reconstrucción del muro: ''las fuerzas de los cargadores desfallecen''. El Salmo 81:6 celebra la liberación: ''Aparté su hombro de la carga'', Dios aliviando a Israel de la esclavitud egipcia. La palabra abarca tanto las cargas físicas llevadas sobre los hombros como el peso opresivo de la servidumbre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5448', 'spa', 'carga (de tiranía); peso opresivo de dominio extranjero o subyugación', 'Este sustantivo, distinto del similar H5447, denota específicamente la carga de tiranía u opresión, siempre en sentido figurado. Aparece tres veces en Isaías, describiendo consistentemente el peso de la dominación extranjera que Dios quitará. Isaías 9:4 celebra la liberación: ''el yugo de su carga'' quebrantado como en el día de Madián. Isaías 10:27 profetiza que ''su carga se apartará de tu hombro'', el fin de la opresión asiria. Isaías 14:25 promete ''quebrantar a Asiria en mi tierra, y su carga se apartará de ellos''. No se trata de simple cargamento pesado, sino del peso aplastante de la subyugación: opresión política, económica y espiritual bajo señores extranjeros.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5449', 'spa', 'Cargador, obrero que transporta cargas pesadas para construcción o acarreo', 'Sustantivo del hebreo tardío que designa al que carga pesos, usado colectivamente para los obreros reclutados en grandes proyectos de construcción. Salomón empleó decenas de miles de estos trabajadores junto con canteros para el Templo (1 R 5:15; 2 Cr 2:2, 18), y Josías los organizó de manera similar para las reparaciones del Templo (2 Cr 34:13). En Nehemías 4:10, la fuerza desfalleciente de los cargadores se convierte en metáfora del desánimo del pueblo durante la reconstrucción de la muralla. El término evoca el trabajo manual colectivo y pesado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5450', 'spa', 'Carga o trabajo forzado; las cargas pesadas y la servidumbre obligatoria impuestas a Israel durante la esclavitud en Egipto.', 'Sustantivo femenino que aparece exclusivamente en la narrativa del Éxodo para describir las cargas y el trabajo forzado impuestos a los israelitas en Egipto. Abarca tanto las cargas físicas transportadas como el sistema más amplio de servidumbre obligatoria. Faraón se queja de que Moisés distrae al pueblo «de sus cargas» (Éx 5:4-5), mientras que Dios promete sacar a Israel «de debajo de las cargas de Egipto» (Éx 6:6-7). La palabra aparece por primera vez cuando Faraón pone capataces sobre Israel «con sus cargas» para afligirlos (Éx 1:11), y Moisés contempla esas cargas de primera mano (Éx 2:11).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5456', 'spa', 'Postrarse o inclinarse en adoración; usado exclusivamente para la adoración de ídolos en Isaías 44-46.', 'Verbo que significa postrarse en adoración o veneración, probablemente un préstamo del arameo que aparece exclusivamente en la sátira de Isaías contra la fabricación de ídolos (capítulos 44-46). El profeta emplea repetidamente esta palabra para exponer lo absurdo de inclinarse ante un objeto que uno mismo acaba de tallar en madera, el mismo árbol usado como leña para cocinar. En Isaías 44:15,17,19, el artesano fabrica un ídolo y luego «se postra» ante él, y en 46:6 las personas se postran ante el ídolo de oro que encargaron. El matiz arameo de la palabra (compárese con el arameo seged y el árabe sajada, de donde deriva «mezquita/masjid») puede haber sido elegido deliberadamente para ridiculizar las prácticas de culto extranjero.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5457', 'spa', 'Adorar, postrarse (arameo) — inclinarse en homenaje o veneración religiosa ante un ídolo o un rey', 'El verbo arameo סְגִד (segid) significa postrarse en adoración o rendir homenaje, y se usa exclusivamente en Daniel. Aparece de manera prominente en el relato de la estatua de oro: se ordena a todos los pueblos «postrarse y adorar» al son de los instrumentos (Dn 3:5-7, 10-12, 14-15, 18, 28). El verbo se empareja con נְפַל («caer») formando una vívida expresión doble. Nabucodonosor también realiza este acto ante Daniel tras la revelación del sueño (Dn 2:46). El cognado árabe sajada pervive en masjid («mezquita», literalmente «lugar de postración»). El español «adorar» capta bien la dimensión reverencial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5459', 'spa', 'Posesión atesorada, propiedad especial; usado teológicamente de Israel como pueblo escogido de Dios y de tesoro real.', 'Sustantivo que designa una posesión personal preciada o un tesoro, empleado con gran fuerza en la teología del pacto para describir la relación única de Israel con Dios. En el Sinaí, YHWH declara: «vosotros seréis mi סְגֻלָּה» — mi posesión atesorada entre todos los pueblos (Éx 19:5), frase que resuena en Deuteronomio 7:6, 14:2 y 26:18. El término también aparece en contextos seculares para referirse al tesoro privado de un rey en oro y plata (1 Cr 29:3; Ecl 2:8). La doble dimensión del vocablo —relacional y material— revela que lo esencial no es el valor económico, sino la elección personal y afectiva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5460', 'spa', 'Prefecto, gobernador provincial o alto funcionario administrativo del imperio babilónico-persa', 'Sustantivo arameo que designa a un alto funcionario provincial en la jerarquía administrativa babilónico-persa. Las cinco ocurrencias aparecen en Daniel, donde los prefectos se enumeran junto a sátrapas, consejeros y jueces en listas formales de oficiales imperiales (Dn 3:2-3, 27). Daniel mismo es elevado por encima de estos prefectos tras interpretar el sueño de Nabucodonosor (Dn 2:48), y los funcionarios de Darío conspiran entre ellos (Dn 6:7). El término es un préstamo asirio que refleja la estructura burocrática mesopotámica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5461', 'spa', 'Prefecto, funcionario provincial: gobernador o administrador designado, tomado del acadio šaknu, aplicado a líderes asirios, babilónicos y judíos pose', 'Prefecto, funcionario provincial: gobernador o administrador designado, tomado del acadio šaknu, aplicado a líderes asirios, babilónicos y judíos posexílicos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5462', 'spa', 'Cerrar, clausurar, entregar, poner en cuarentena o confinar; del oro: puro, refinado; en Pual: firmemente atrancado.', 'Cerrar, clausurar, entregar, poner en cuarentena o confinar; del oro: puro, refinado; en Pual: firmemente atrancado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5466', 'spa', 'vestidura de lino, lienzo; pieza rectangular de lino fino usada como prenda exterior', 'Este término designa una vestidura o lienzo de lino fino, probablemente de forma rectangular, que se usaba como prenda exterior o, por la noche, como única cobertura. En Jueces 14:12-13, Sansón ofrece treinta vestiduras de lino como parte de su apuesta con un acertijo. Proverbios 31:24 elogia a la mujer virtuosa que confecciona y vende tales prendas. Isaías 3:23 las incluye entre los artículos de lujo de las mujeres acaudaladas de Jerusalén. El vocablo podría ser un préstamo lingüístico, posiblemente relacionado con el griego σινδών.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5467', 'spa', 'Sodoma — antigua ciudad de la llanura del Jordán destruida por juicio divino; proverbial por su maldad.', 'Sodoma — antigua ciudad de la llanura del Jordán destruida por juicio divino; proverbial por su maldad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5470', 'spa', 'Prisión, casa redonda; la cárcel de estilo egipcio donde José fue encarcelado.', 'Sustantivo que aparece exclusivamente en la narrativa de José (Gn 39-40) para designar la prisión donde fue encarcelado tras la falsa acusación de la esposa de Potifar. La expresión completa es בֵּית הַסֹּהַר (''casa del סֹהַר''), posiblemente derivada de un préstamo egipcio que significa ''casa redonda'' o ''recinto''. Todas las ocurrencias se concentran en Génesis 39:20-40:5, describiendo el lugar donde Potifar puso a José, donde YHWH le mostró su misericordia, y donde más tarde fueron confinados el copero y el panadero del faraón.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5472', 'spa', 'Retroceder, retirarse; apostatar o apartarse de Dios; desviarse, extraviarse del camino recto', 'Un verbo hebreo cuyas formas Nifal y Qal trazan un espectro que va desde la retirada física hasta la apostasía espiritual. En los Salmos, la palabra describe frecuentemente a los enemigos siendo rechazados o forzados a retroceder (Sal 35:4; 40:14; 70:2). Sin embargo, los profetas la transforman en uno de los términos más incisivos de la Biblia para la defección espiritual: el ''apóstata de corazón'' de Proverbios 14:14, el voto angustiado ''no nos apartaremos de ti'' en el Salmo 80:18, y la denuncia de Sofonías contra quienes ''se apartaron de seguir al SEÑOR'' (Sof 1:6). Una aparición aislada en Qal en el Salmo 53:3 — ''todos se desviaron'' — capta el extravío moral fuera del camino recto, matiz distinto tanto de la retirada militar como de la apostasía deliberada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5475', 'spa', 'Consejo confidencial o asamblea; un círculo íntimo de personas de confianza, su deliberación compartida o un plan secreto.', 'Consejo confidencial o asamblea; un círculo íntimo de personas de confianza, su deliberación compartida o un plan secreto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5480', 'spa', 'Ungir o frotar con aceite, ya sea para el aseo personal, la preparación ceremonial o como señal del fin del duelo.', 'A diferencia del más solemne מָשַׁח (usado para consagrar reyes y sacerdotes), este verbo describe el acto cotidiano y personal de frotarse aceite en el cuerpo. Noemí le dice a Rut que se lave y se unja antes de presentarse ante Booz (Rt 3:3). David se levanta del duelo, se lava y se unge (2 S 12:20). A la mujer de Tecoa se le dice que actúe como quien guarda luto y no se ha ungido (2 S 14:2). Deuteronomio 28:40 advierte de una maldición tan severa que cultivarán olivos pero nunca se ungirán. Daniel se abstiene de ungirse durante su ayuno de tres semanas (Dn 10:3). En Ezequiel 16:9, Dios relata con ternura haber ungido a Jerusalén como acto de cuidado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5481', 'spa', 'gaita, flauta doble; instrumento de viento en la orquesta de Nabucodonosor', 'Este es otro instrumento musical de la orquesta real de Daniel 3, probablemente un instrumento de viento como una gaita, flauta doble o flauta de Pan. El término es un préstamo del griego tardío συμφωνία, del cual derivan palabras modernas como «sinfonía». La palabra presenta variantes textuales: el ketiv registra סִימְפּוֹן o סִיפְנְיָה en algunos versículos, mientras que el qeré lee סוּפֹּנְיָה o סוּמְפֹּנְיָה. El instrumento refleja la influencia cultural helenística en el período neobabilónico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5483b', 'spa', 'Caballo: animal doméstico empleado para la guerra, el transporte y la exhibición real en la narrativa bíblica.', 'El hebreo סוּס aparece en casi todos los géneros de la Escritura, desde la narrativa patriarcal (Gn 47:17) hasta la visión apocalíptica (Zac 1:8). Los caballos en el mundo de Israel se asociaban abrumadoramente con el poderío militar: los caballos de los carros del faraón ahogándose en el Mar (Éx 15:1, 21), los carros de guerra cananeos (Jos 11:4) y las polémicas importaciones de caballería de Salomón desde Egipto (1 R 10:28). Los profetas advirtieron repetidamente contra confiar en caballos en lugar de en el Señor (Is 31:1; Sal 20:7). Todas las grandes lenguas de traducción lo vierten con su término equino estándar: caballo, cheval, Pferd, cavallo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5486', 'spa', 'Llegar a su fin, cesar, perecer, ser arrebatado; en causativo, consumir o barrer en juicio divino.', 'Verbo de terminación y destrucción. El Qal describe cosas o personas que dejan de existir: los impíos son «arrebatados por terrores» (Sal 73:19), las casas de marfil «llegarán a su fin» (Am 3:15), y la memoria de Purim «no cesará» entre los judíos (Est 9:28). El Hifil convierte esto en juicio divino activo: Dios declara «destruiré por completo» (Sof 1:2) y «los recogeré para destrucción» (Jer 8:13). La distinción entre Qal e Hifil refleja el contraste entre perecer pasivamente y ser consumido por acción divina deliberada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5488', 'spa', 'Juncos o cañas acuáticas; vegetación acuática, célebremente asociada con Yam Suph (Mar de los Juncos)', 'Juncos o cañas acuáticas; vegetación acuática, célebremente asociada con Yam Suph (Mar de los Juncos)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5490', 'spa', 'fin, conclusión, punto terminal de un asunto, lugar o proceso', 'Sinónimo tardío del más frecuente קֵץ, que designa el punto terminal de algo, ya sea espacial, temporal o conceptual. Marca el final del valle donde el ejército de Josafat halló botín (2 Cr 20:16), la retaguardia de una plaga de langostas arrojada al mar (Jl 2:20) y el alcance incomprensible de la obra divina de principio a fin (Ecl 3:11). En Eclesiastés 12:13 funciona como la gran recapitulación: la conclusión de todo el discurso. Su versatilidad se refleja en las diversas traducciones españolas: ''el fin,'' ''al final de,'' ''fin de.''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5491', 'spa', 'fin, conclusión, extremo (arameo); punto final de un asunto, lugar o duración', 'Cognado arameo del hebreo סוֹף, utilizado exclusivamente en Daniel para indicar un fin o extremo. Describe el alcance de un gran árbol que se extiende hasta el confín de la tierra en el sueño de Nabucodonosor (Dn 4:11, 22), la naturaleza eterna del dominio de Dios (Dn 6:26, ''hasta el fin''), la destrucción de un dominio en el tiempo señalado (Dn 7:26) y el cierre del relato visionario de Daniel (Dn 7:28). La traducción española consistente ''fin/el fin'' confirma un significado cohesivo único en todos los contextos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5492a', 'spa', 'Torbellino violento o tempestad, frecuentemente imagen del juicio repentino y arrasador de Dios o de una fuerza destructiva abrumadora.', 'En la literatura profética y sapiencial, el hebreo sûphâ designa el viento huracanado y feroz que barre la era y dispersa la paja sin remedio. Amós y Nahúm lo emparejan con la tormenta común (seʿārâ) para intensificar la imagen de la furia divina (Am 1:14; Na 1:3). El célebre proverbio de Oseas — «siembran viento y cosechan sûphâ» (Os 8:7) — convierte la palabra en sinónimo de consecuencias que superan con creces su causa. Isaías compara la velocidad de las ruedas de los carros con la del torbellino (Is 5:28), mientras Proverbios advierte que la ruina llega «como sûphâ» sobre los confiados (Pr 1:27). En español se traduce habitualmente como «torbellino» o «tempestad», captando la violencia rotatoria que implica el hebreo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5493', 'spa', 'Apartarse, quitar, desviarse o marcharse; abarca desvío físico, remoción, partida, desviación moral y voz pasiva.', 'סוּר describe un movimiento que se aparta de la trayectoria esperada, ya sea un viajero que se desvía del camino, un rey que retira ídolos o un corazón que se aleja de Dios. El Qal capta el movimiento autoiniciado (apartarse, marcharse), mientras que el Hifil añade fuerza causativa (quitar objetos, purgar el mal). Su registro moral transforma la desviación literal del camino en una poderosa metáfora de apostasía y fidelidad. Desde Moisés apartándose ante la zarza ardiente (Éx 3:3-4) hasta la acusación profética contra los que ''se apartan'' de los mandamientos, סוּר traza la geografía de la obediencia y la rebelión.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5496', 'spa', 'Incitar, seducir, atraer; en Hifil, instar a alguien a la acción, frecuentemente con connotaciones negativas de seducción o engaño.', 'Incitar, seducir, atraer; en Hifil, instar a alguien a la acción, frecuentemente con connotaciones negativas de seducción o engaño.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5498', 'spa', 'arrastrar, llevar a rastras por la fuerza; arrastrar cadáveres, cautivos u objetos por el suelo', 'Verbo que transmite la acción de arrastrar algo o a alguien con violencia, siempre con connotaciones de fuerza bruta o compulsión. Husai propone arrastrar una ciudad entera con sogas hasta un barranco (2 S 17:13), mientras Jeremías profetiza cadáveres arrastrados por las puertas de Jerusalén (Jer 15:3; 22:19) y cautivos llevados a rastras como ovejas atrapadas por un depredador (Jer 49:20 = 50:45). El español ''arrastrar'' y el inglés ''drag'' preservan por igual la fisicidad visceral de la acción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5499', 'spa', 'harapos, ropa vieja y gastada; tiras de tela deteriorada', 'Este sustantivo femenino plural designa harapos o tiras de tela gastada, tejido tan deteriorado que solo sirve para los usos más humildes. Jeremías 38:11-12 lo emplea dos veces en el relato del rescate de Jeremías de la cisterna. Ebed-melec toma ''harapos y ropas viejas'' del almacén del palacio, los baja con cuerdas a Jeremías y le indica que ''ponga los trapos y ropas viejas debajo de sus axilas bajo las cuerdas'' para evitar que las sogas le lastimen la piel al subirlo. Este detalle compasivo de usar trapos suaves para amortiguar el rescate resalta tanto la condición desesperada de Jeremías como el cuidado atento de su rescatador.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5500', 'spa', 'raspar, rascar hasta dejar desnudo o limpio por completo', 'Este verbo describe la acción de raspar algo hasta dejarlo completamente limpio, eliminando todo rastro de material superficial. Ezequiel lo emplea en un oráculo profético contra Tiro, declarando que Dios raspará hasta el polvo de la ciudad, dejándola como una roca pelada. La imagen es de desolación total: no solo la destrucción de edificios, sino la remoción de todo vestigio de habitación humana. El cognado árabe comparte el sentido de raspar o despejar a fondo. Este raspado divino transforma una metrópolis bulliciosa en piedra yerma.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5501', 'spa', 'desecho, despojo, inmundicia; residuos que se descartan', 'Este sustantivo áspero designa las raspaduras o residuos que se acumulan y deben descartarse, esencialmente basura o inmundicia. Lamentaciones lo emplea en una devastadora autodescripción: «Nos has hecho desecho y basura en medio de los pueblos». El término capta el sentimiento de Israel de ser tratado como desperdicio sin valor por las naciones circundantes durante el exilio. Pablo adopta un lenguaje similar en 1 Corintios, llamando a los apóstoles «desecho de todos». La palabra encarna la inversión absoluta: de pueblo escogido a basura descartada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5503', 'spa', 'Ir de un lado a otro como comerciante o viajero; como participio, mercader; por extensión, palpitar o latir.', 'Ir de un lado a otro como comerciante o viajero; como participio, mercader; por extensión, palpitar o latir.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5504', 'spa', 'comercio, ganancia del comercio; mercancía, beneficio o rédito comercial', 'Este sustantivo se refiere al beneficio o ganancia derivados del comercio y el intercambio mercantil. Proverbios lo emplea dos veces para describir la ganancia superior de la sabiduría y el trabajo provechoso de la mujer virtuosa (3:14, 31:18). Isaías lo utiliza en oráculos sobre Tiro, la gran ciudad mercantil, donde el «comercio» o ganancia comercial de Tiro será finalmente consagrado al Señor (23:3, 18). El término enfatiza la dimensión económica del intercambio y los réditos que genera.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5505', 'spa', 'Mercancía, ganancia del comercio; beneficio obtenido de la actividad mercantil', 'Este sustantivo masculino designa la ganancia o beneficio derivado del comercio. Proverbios celebra el valor de la sabiduría: «mejor es su ganancia que la ganancia de la plata» (3:14), usando el término dos veces para enfatizar. Isaías describe la «mercancía» de Tiro (23:3) y profetiza que «su mercancía y su salario» serán consagrados al SEÑOR (23:18). Isaías 45:14 promete que «la riqueza de Egipto y la mercancía de Cus» vendrán a Israel. El vocablo no alude a los bienes mismos, sino al rédito generado por el intercambio comercial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5506', 'spa', 'mercancía, artículos de comercio', 'Este sustantivo se refiere a artículos de comercio, los bienes que los mercaderes itinerantes ofrecen a la venta. Ezequiel lo emplea en su elaborado oráculo contra Tiro, catalogando los numerosos pueblos que llevaban sus mercancías a este gran centro comercial. El término aparece en forma constructa, «la mercancía de», vinculando diversas naciones con sus productos comerciales. La riqueza de Tiro provenía de ser un nexo del comercio internacional, y esta palabra captura el flujo constante de mercancías por sus mercados. La caída de la ciudad significaría no solo un colapso político sino el fin de esta vasta red comercial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5507', 'spa', 'rodela, escudo pequeño (arma defensiva)', 'Este término designa un tipo de escudo defensivo o rodela, y aparece en la célebre promesa de protección divina del Salmo 91. El salmista declara que la fidelidad de Dios es «escudo y rodela», empleando dos términos defensivos emparejados para enfatizar una protección completa. La rodela era típicamente más pequeña y manejable que el escudo grande (צִנָּה), y se portaba para desviar golpes en combate cercano. El uso metafórico del equipamiento militar para representar el cuidado protector de Dios habría resonado profundamente en un mundo donde la guerra era constante y la armadura significaba la diferencia entre la vida y la muerte.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5508', 'spa', 'piedra de color, piedra oscura (posiblemente mármol o pórfido)', 'Esta palabra infrecuente describe un tipo de piedra decorativa empleada en el lujoso pavimento del jardín del palacio del rey Asuero. Ester 1 la enumera junto al mármol y otros materiales preciosos al describir el opulento escenario del gran banquete real. El tipo exacto de piedra es incierto: las posibilidades incluyen pórfido, mármol negro u otra piedra de color valorada en la arquitectura persa. El cognado asirio «siḫru» se refiere a una piedra preciosa, lo que sugiere que se trataba de un material importado o extraído especialmente que señalaba riqueza y magnificencia real.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5509', 'spa', 'Escoria o impureza metálica; el residuo que se separa del metal durante la fundición, usado figuradamente para la impureza moral.', 'Designa el material de desecho que se separa de los metales preciosos durante el proceso de refinación. Los profetas emplearon esta imagen metalúrgica con gran fuerza: Isaías declara que la plata de Jerusalén se ha convertido en escoria (Is 1:22), y Ezequiel retrata a toda la casa de Israel como escoria en el horno de Dios (Ez 22:18-19). Proverbios lo utiliza tanto en sentido literal, describiendo la remoción de la escoria para purificar la plata (Pr 25:4), como en sentido figurado, comparando las palabras hipócritas con un tiesto recubierto de escoria de plata (Pr 26:23). La imagen de la fundición trasciende épocas y culturas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5510', 'spa', 'Siván, el tercer mes del calendario hebreo (mayo-junio)', 'Siván es el tercer mes del calendario hebreo, que corresponde aproximadamente a mayo-junio en el calendario moderno. El nombre aparece en el libro de Ester al fechar el contraedicto de Mardoqueo, que fue enviado «el día veintitrés del mes tercero, que es el mes de Siván». Se trata de un préstamo del acadio Simānu, reflejo de la influencia babilónica en la terminología calendárica judía durante y después del exilio. El mes cae en la primavera tardía, época de la cosecha de granos en el antiguo Israel. Solo los textos bíblicos postexílicos emplean los nombres babilónicos de los meses en lugar del sistema cananeo anterior.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5511', 'spa', 'Sihón — el rey amorreo de Hesbón derrotado por Israel, cuyo territorio se convirtió en la primera conquista en Canaán.', 'Sihón — el rey amorreo de Hesbón derrotado por Israel, cuyo territorio se convirtió en la primera conquista en Canaán.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5512b', 'spa', 'Sin; región desértica entre Elim y el Sinaí donde Israel acampó durante el Éxodo', 'El Desierto de Sin es una zona árida en la ruta del Éxodo, situada entre Elim y el monte Sinaí, mencionada en la fuente sacerdotal. Según Éxodo 16:1, Israel llegó allí el día quince del segundo mes, y fue donde Dios proveyó el maná y las codornices. Números 33:11-12 lo incluye en el itinerario de las peregrinaciones de Israel por el desierto. Este nombre no debe confundirse con la ofrenda por el pecado ni con la ciudad de Sin (Pelusio) en Egipto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5514', 'spa', 'Sinaí — el monte sagrado y desierto donde Dios entregó la Torá a Moisés.', 'Sinaí — el monte sagrado y desierto donde Dios entregó la Torá a Moisés.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5515', 'spa', 'Sinim, un pueblo o tierra lejana mencionada en Isaías', 'Sinim aparece en la profecía de Isaías sobre la restauración de Israel, cuando los exiliados regresarán «del norte y del occidente, y estos de la tierra de Sinim». Su identificación ha desconcertado a los intérpretes durante siglos. Las propuestas tempranas incluían China (por similitud fonética), pero esto parece improbable dado el contexto histórico. Más probable es una enmienda a «sienitas» (habitantes de Siena/Asuán en el sur de Egipto), lo cual proporcionaría un equilibrio geográfico preciso: norte, occidente y sur. El texto tal como está apunta hacia los confines conocidos de la tierra, subrayando la totalidad del regreso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5516', 'spa', 'Sísara: comandante cananeo bajo el rey Jabín de Hazor, derrotado por Débora y Barac; también nombre de una familia posexílica.', 'Sísara: comandante cananeo bajo el rey Jabín de Hazor, derrotado por Débora y Barac; también nombre de una familia posexílica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5518a', 'spa', 'Olla o caldero para cocinar y hervir; raramente un lebrillo o palangana usada para lavar', 'Olla o caldero para cocinar y hervir; raramente un lebrillo o palangana usada para lavar');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5518b', 'spa', 'espino, zarza; también anzuelo o garfio (para pescar o arrastrar)', 'Sustantivo con dos acepciones distintas pero emparentadas, ambas enraizadas en la idea de algo punzante y penetrante. Como ''espinos,'' aparece en imágenes de desolación (Is 34:13), como barrera que Dios pone en el camino de la infiel (Os 2:8) y en el vívido símil del Qohélet sobre espinos que crepitan inútilmente bajo una olla (Ecl 7:6). Como ''anzuelos'' o ''garfios,'' describe los instrumentos con que Amós advierte que las mujeres de Samaria serán arrastradas (Am 4:2). El nexo semántico entre ambos sentidos es lo agudo, lo que pincha y engancha.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5519', 'spa', 'multitud, tropel, masa densa de personas', 'Este sustantivo describe una multitud apiñada o tropel de personas apretadas unas contra otras. El salmista recuerda tiempos mejores: «Yo solía caminar entre la multitud», procesionando hacia el templo en medio de la alegre muchedumbre festiva. El término sugiere una masa entretejida, personas tan estrechamente agrupadas que forman una sola entidad en movimiento. Algunas versiones traducen «cabaña» o «refugio», pero el contexto de peregrinación festiva favorece el sentido de una gran multitud. El recuerdo de la adoración comunitaria intensifica el aislamiento y la añoranza actuales del salmista.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5520', 'spa', 'matorral, guarida, escondrijo; vegetación densa que sirve de refugio, especialmente para animales depredadores', 'Este término designa un matorral denso o escondrijo, utilizado con frecuencia como imagen de la guarida de un león. En el Salmo 10:9 se compara al malvado con un león al acecho «en su guarida», mientras que Jeremías 25:38 emplea la imagen de un león que abandona «su escondrijo» para describir el juicio divino. El Salmo 76:3 podría referirse al refugio o morada de Dios, aunque algunos enmiendan el texto. El término se solapa semánticamente con סְבַךְ (matorral) y puede derivar de la misma raíz o de una relacionada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5521', 'spa', 'Cabaña, refugio temporal de ramas; la Fiesta de las Cabañas (Sukkot); dosel protector de Dios; espesura o matorral', 'Cabaña, refugio temporal de ramas; la Fiesta de las Cabañas (Sukkot); dosel protector de Dios; espesura o matorral');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5522', 'spa', 'Sikut, nombre de una deidad asiria (posiblemente Saturno/Adar-Ninip)', 'Esta palabra probablemente designa a una deidad mesopotámica adorada por israelitas que habían sincretizado su fe con prácticas religiosas asirias. Amós condena a quienes «llevaron a Sikut vuestro rey y a Quiyún vuestras imágenes», refiriéndose a divinidades astrales asociadas con la conquista asiria. La mayoría de los eruditos identifican a Sikut con Sakkut, un epíteto de Adar-Ninip, relacionado con el planeta Saturno. Las versiones antiguas tuvieron dificultades con el término; algunas lo leyeron como «cabaña» (sucá), pasando por alto el nombre propio. La acusación del profeta es grave: Israel no solo había caído en una idolatría genérica, sino que había adoptado los dioses de sus opresores.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5523', 'spa', 'Sucot: ''cabañas,'' ciudad en Transjordania vinculada a Jacob; también punto de partida del éxodo en Egipto.', 'Sucot: ''cabañas,'' ciudad en Transjordania vinculada a Jacob; también punto de partida del éxodo en Egipto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5525', 'spa', 'Suquienos, un pueblo africano en el ejército de Sisac', 'Los suquienos formaban parte de la diversa fuerza militar que el faraón egipcio Sisac llevó contra la Jerusalén de Roboam. Enumerados junto a libios y cusitas, representan uno de los contingentes africanos en esta invasión temprana del quinto año del reinado de Judá. Las versiones antiguas los identifican como «trogloditas» (moradores de cuevas), aunque la identificación precisa sigue siendo incierta. El término muestra cómo los ejércitos de Egipto reclutaban de una amplia base geográfica, incorporando diversos pueblos de regiones al sur y al oeste del delta del Nilo. Su presencia subraya la escala internacional de la amenaza que enfrentaba el reino recién dividido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5526b', 'spa', 'Cubrir, proteger o resguardar (como los querubines sobre el arca); en un tronco Piel distinto, incitar o provocar conflicto.', 'Cubrir, proteger o resguardar (como los querubines sobre el arca); en un tronco Piel distinto, incitar o provocar conflicto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5526c', 'spa', 'tejer, entretejer; formar entrelazando elementos, como la obra divina al crear al ser humano en el vientre', 'Este verbo describe la labor minuciosa de tejer o entretejer, utilizado metafóricamente para referirse al acto creador de Dios al formar al ser humano en el vientre materno. El salmista exclama maravillado: «Tú me tejiste en el vientre de mi madre», reconociendo la maestría divina en la formación humana. La imagen no sugiere un ensamblaje aleatorio, sino una construcción artística y deliberada, donde distintos elementos se entrelazan para formar un todo coherente. El pasaje paralelo en Job emplea la misma raíz para describir el ser tejido con huesos y tendones. Esta poesía biológica presenta al Creador como maestro artesano que teje el tejido mismo de la vida humana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5526d', 'spa', 'cubierta protectora, escudo de asedio (testudo militar)', 'Este término técnico militar designa una cubierta protectora empleada por los atacantes al asaltar una ciudad, lo que los romanos llamarían más tarde testudo o formación de tortuga. Nahúm lo utiliza en su vívido oráculo sobre la caída de Nínive: «la cubierta está preparada». Esta estructura protegía a los soldados de los proyectiles defensivos mientras se aproximaban a las murallas o puertas. El término significa literalmente «aquello que cubre o resguarda», mostrando cómo la tecnología bélica incluía equipo defensivo sofisticado. El punto del profeta es que, incluso con preparativos militares adecuados, la capital asiria no puede escapar del juicio divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5526e', 'spa', 'cubrir, resguardar, proteger; ocultar con cobertura protectora', 'Este verbo significa cubrir algo o a alguien proporcionando protección u ocultamiento. En Éxodo, cuando Moisés pide ver la gloria de Dios, Yahvé le promete: «Te cubriré con mi mano mientras paso». El gesto protege a Moisés del resplandor pleno e inmediato de la gloria divina, que nadie puede contemplar y seguir con vida. La cobertura es a la vez misericordiosa y necesaria: permite una revelación parcial al tiempo que previene la destrucción. El sentido básico del verbo es cubrir físicamente, pero aquí se convierte en el medio por el cual Dios acomoda su presencia abrumadora a la fragilidad humana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5526f', 'spa', 'tejer, entretejer; formar entrelazando huesos y tendones, obra divina de creación corporal', 'Esta variante de la raíz también describe tejer o entretejer, y aparece en la meditación de Job sobre la obra creadora de Dios. Job recuerda cómo Dios «me tejió» con huesos y tendones, los tejidos estructurales y conectivos que forman el armazón del cuerpo. La forma Piel intensifica la acción, sugiriendo un trabajo cuidadoso y repetido. El versículo es paralelo a la imaginería similar del Salmo 139:13, pues ambos textos emplean metáforas textiles para la formación biológica. Los pueblos antiguos, familiarizados con el telar, habrían apreciado cómo este oficio —entrelazar hilos separados para crear un tejido fuerte— refleja la integración de las partes del cuerpo en un organismo vivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5527', 'spa', 'Secacá, una ciudad en el desierto de Judá', 'Secacá era un asentamiento en el distrito desértico de Judá, mencionado entre las ciudades en las asignaciones territoriales de Josué. Su ubicación precisa permanece desconocida, perdida junto con muchos otros asentamientos del desierto que no dejaron huellas arqueológicas perdurables. El desierto de Judá estaba escasamente poblado, con ciudades dispersas que servían como puestos avanzados en el terreno áspero entre la cordillera central y el Mar Muerto. Las versiones antiguas transliteran el nombre de forma diferente —Σοχοχα, Σχαχα— reflejando incertidumbres de pronunciación. La inclusión de esta ciudad en las asignaciones tribales demuestra una organización sistemática incluso en territorios marginales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5528', 'spa', 'Obrar neciamente, comportarse insensatamente; hacer necio, convertir en locura.', 'El verbo סָכַל abarca el campo de la necedad tanto en su dimensión intransitiva como causativa. En sus formas Nifal e Hifil describe a quien ha obrado neciamente — la punzante autocrítica que Saúl confiesa a David: «yo he obrado neciamente» (1 S 26:21), eco que repite David mismo tras el censo (2 S 24:10). El Piel traslada la agencia hacia afuera: Dios «enloquece» el consejo de los sabios (Is 44:25), y David ora para que el consejo de Ahitofel sea «convertido en necedad» (2 S 15:31). Los cognados siríaco y arameo confirman esta raíz pansemítica de la insensatez moral e intelectual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5529', 'spa', 'necio, persona insensata', 'Este sustantivo designa a un necio o persona insensata, y aparece en la observación irónica del Eclesiastés sobre el orden invertido de la vida bajo el sol. Qohélet señala que «al necio lo colocan en las alturas», una inversión del orden justo donde la sabiduría debería ser honrada y la necedad rechazada. El término comparte raíz con palabras que denotan insensatez y falta de entendimiento, subrayando una deficiencia tanto moral como intelectual. En la literatura sapiencial, el necio no es simplemente ignorante sino obstinado, rechazando la instrucción y siguiendo caminos autodestructivos. La queja del Predicador refleja la decepción ante un mundo donde el mérito y la posición no se corresponden.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5530', 'spa', 'Necio, insensato; persona moralmente obtusa, torpe o tercamente imprudente.', 'Sustantivo de la literatura sapiencial para designar al necio — alguien marcado no solo por la ignorancia sino por la obstinación moral e intelectual. Aparece casi exclusivamente en Eclesiastés, donde Qohélet examina la futilidad de dejar el fruto de su trabajo a un necio (Ecl 2:19), advierte contra ser excesivamente malvado o insensato (7:17) y observa cómo el necio exhibe su falta de juicio incluso al caminar por la calle (10:3). Jeremías también lo emplea con dureza: «mi pueblo es necio, no me conoce» (Jer 4:22; 5:21). El término connota una necedad voluntaria, no simple ingenuidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5531a', 'spa', 'necedad, insensatez', 'Este sustantivo abstracto designa la necedad o conducta insensata, lo opuesto a la sabiduría que Eclesiastés examina repetidamente. Qohélet lo incluye en su exploración integral: «Apliqué mi corazón a conocer la sabiduría y a conocer la locura y la necedad». La palabra aparece múltiples veces en Eclesiastés, siempre como algo que debe comprenderse, no practicarse. Ocasionalmente escrita con שׁ en lugar de ס (variación escribal), representa el polo negativo en el universo moral de la sabiduría. La necedad no es diversión inocente sino estupidez destructiva, del tipo que arruina vidas, relaciones y comunidades. El Predicador la estudia cuidadosamente para comprender la conducta humana bajo el sol.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5531b', 'spa', 'Necedad, insensatez; lo opuesto a la sabiduría, examinado filosóficamente en Eclesiastés.', 'Sustantivo femenino abstracto que significa necedad o insensatez, aparece exclusivamente en Eclesiastés como contraparte conceptual de la sabiduría (chokmah). Qohélet investiga sistemáticamente la necedad junto a la sabiduría, declarando que «se volvió a considerar la sabiduría, la locura y la necedad» (Ecl 2:12). Observa que la sabiduría supera a la necedad como la luz supera a las tinieblas (2:13), aunque el mismo destino alcanza tanto al sabio como al necio. En Eclesiastés 7:25, el predicador aplica su corazón a conocer «la maldad de la necedad y la insensatez de la locura». La palabra aparece en la mayoría de los casos con artículo o waw conjuntiva, tratada como una categoría filosófica conocida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5532', 'spa', 'Ser útil o provechoso; servir como cuidador o mayordomo; (Hifil) estar familiarizado con, acostumbrarse', 'Una raíz versátil que abarca servicio, provecho e intimidad. En los diálogos de Job, explora si algún ser humano puede verdaderamente «ser provechoso» a Dios, un desafío teológico traducido de manera consistente en todas las lenguas. Como participio se convierte en título personal: Abisag, la «cuidadora» que daba calor al anciano rey David, y Sebna, el «mayordomo» a quien Isaías confrontó. En el Hifil, el sentido pasa a la familiaridad relacional, como en Job 22:21: «Reconcíliate con Dios», literalmente, hazte íntimamente cercano a Él.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5533a', 'spa', 'estar en peligro, correr riesgo', 'Este verbo hebreo tardío significa exponerse al peligro o correr riesgo. Eclesiastés lo emplea para observar que «el que raja leña se pone en peligro con ella», una sentencia proverbial sobre los riesgos del trabajo cotidiano. El término aparece únicamente en literatura postexílica y refleja influencia aramea, mostrando cómo el hebreo absorbió vocabulario de su entorno lingüístico durante el exilio. La literatura rabínica desarrolló posteriormente un uso abundante del sustantivo «peligro» (sakkaná) derivado de esta raíz. El argumento de Qohélet es que incluso el trabajo ordinario conlleva riesgo; las incertidumbres de la vida se extienden a las actividades más rutinarias.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5533b', 'spa', 'empobrecido, persona pobre (posiblemente)', 'Esta palabra difícil aparece en la descripción satírica de Isaías sobre la fabricación de ídolos. El texto se refiere a «el que es demasiado pobre para ofrenda», alguien tan necesitado que no puede costear un ídolo apropiado y quizá recurre a la madera en vez del metal. Sin embargo, la lectura es muy debatida y existen numerosas conjeturas académicas. Algunos lo relacionan con la raíz de «pobre» (meskén), mientras otros proponen enmiendas textuales. El pasaje critica la idolatría resaltando lo absurdo: incluso los empobrecidos se esfuerzan por hacerse dioses, preservando cuidadosamente una imagen de madera que no se pudra. La oscuridad del versículo no ha mermado su fuerza satírica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5534', 'spa', 'Cerrar, tapar, obstruir; clausurar o confinar bloqueando', 'Este verbo significa cerrar, tapar u obstruir, y se usa para sellar manantiales y acallar bocas. Génesis 8:2 describe el retroceso del diluvio: «las fuentes del abismo y las ventanas de los cielos fueron cerradas», sellando las fuentes del juicio divino. Salmo 63:11 declara que «la boca de los mentirosos será tapada», silenciada por el juicio. Isaías 19:4 advierte que Dios «encerrará a Egipto en manos» de señores crueles, confinándolo bajo dominio extranjero. El verbo sugiere un cierre contundente: manantiales represados, bocas silenciadas, naciones atrapadas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5535', 'spa', 'callar, guardar silencio', 'Este verbo ordena silencio, pidiendo atención callada y concentrada. Moisés lo emplea en un momento decisivo en Deuteronomio: «¡Guarda silencio y escucha, oh Israel!». El mandato precede a la declaración solemne de que Israel se ha convertido en pueblo de Yahvé. El imperativo hifil exige un silencio activo: no una quietud pasiva, sino el cese deliberado de todo ruido para concentrarse por completo en lo que sigue. Los cognados en árabe y siríaco significan igualmente estar callado o en silencio, a menudo en el sentido de escuchar con atención. El verbo reconoce que oír cosas importantes requiere detenerse y crear una quietud receptiva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5536', 'spa', 'Canasta tejida, especialmente para transportar pan y ofrendas horneadas en contextos rituales y ceremoniales.', 'El sal es la sencilla canasta abierta de mimbre conocida por dos escenas bíblicas memorables: el panadero del faraón llevando tres canastas de repostería sobre la cabeza (Gn 40:16–18) y la canasta de panes sin levadura prescrita para la consagración sacerdotal y los ritos de conclusión del nazireato (Éx 29:3, 23; Lv 8:2; Nm 6:15–19). Gedeón también coloca carne y pan en un sal cuando lo visita el ángel (Jue 6:19). En todas sus apariciones la canasta contiene productos horneados, lo que la vincula firmemente con la preparación de alimentos y la ofrenda sagrada, no con el almacenamiento general.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5537', 'spa', 'pesar, estimar como valioso', 'Este verbo hebreo poco común significa pesar o valorar algo, en el sentido de reconocer su valor al compararlo con un estándar de medida. Aparece como participio pual en Lamentaciones 4:2, donde los hijos preciosos de Sion son descritos como «pesados contra el oro fino», es decir, considerados tan valiosos como el oro. La metáfora proviene de la práctica comercial de pesar el oro para establecer su valor. La tragedia radica en que esas mismas personas, antes estimadas más allá de toda medida, ahora son consideradas como vasijas de barro sin valor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5538', 'spa', 'Sila, nombre de lugar (ubicación incierta)', 'Sila aparece en el relato del asesinato del rey Joás, quien fue muerto «en Bet-milo, en el camino que desciende a Sila» (2 Reyes 12:20). La frase es oscura y la ubicación exacta permanece incierta. Algunos eruditos proponen enmendar el texto para leer «calzada» (mesillá) en lugar de «Sila», convirtiéndolo en un sustantivo común en vez de un nombre propio. Otros sugieren leer «la bajada de Milo» sin el nombre geográfico. Las versiones antiguas no aclaran la cuestión. Lo que resulta claro es que el texto sitúa el asesinato de Joás en un lugar específico asociado con Bet-milo, aunque la geografía precisa se ha perdido en la memoria histórica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5539', 'spa', 'saltar, brincar (posiblemente)', 'Este verbo raro e incierto posiblemente significa saltar o brincar, aunque su significado es disputado. Job lo emplea en un pasaje difícil: «saltaría en mi angustia» o «me exaltaría en mi dolor» (Job 6:10). El verbo no aparece en ningún otro lugar del Antiguo Testamento, lo que convierte su significado en una conjetura basada en el uso del hebreo posterior, donde puede significar sobresaltarse o retroceder (como ante el fuego). Algunos intérpretes lo relacionan con la idea de retroceder o encogerse, mientras otros prefieren «saltar de gozo» según el contexto. El punto de Job parece ser que, si pudiera estar seguro de los propósitos de Dios, incluso el sufrimiento produciría algún tipo de respuesta triunfante.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5542', 'spa', 'Selah — anotación litúrgica o musical en los Salmos y Habacuc, de significado incierto; posiblemente una pausa o indicación interpretativa.', 'Selah — anotación litúrgica o musical en los Salmos y Habacuc, de significado incierto; posiblemente una pausa o indicación interpretativa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5543a', 'spa', 'Salai, nombre propio benjaminita', 'Salai aparece en la lista de Nehemías de benjaminitas que se establecieron en Jerusalén después del exilio (Nehemías 11:8). El nombre y el texto circundante presentan dificultades: el pasaje paralelo en 1 Crónicas 9:8 difiere considerablemente, lo que lleva a los eruditos a sospechar corrupción textual. El nombre podría estar relacionado con términos arameos o talmúdicos para recaudadores de impuestos (gabai), aunque esto sigue siendo especulativo. Lo que queda claro es que Salai representa a una de las familias que respondieron al llamado de Nehemías para repoblar Jerusalén, contribuyendo a restaurar la vitalidad demográfica y espiritual de la ciudad tras el regreso de Babilonia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5543b', 'spa', 'Salú, nombre de un sacerdote en tiempos de Zorobabel', 'Salú aparece como nombre sacerdotal durante el período postexílico, cuando Zorobabel dirigía los esfuerzos de reconstrucción en Jerusalén. El nombre se encuentra en la lista de Nehemías de sacerdotes que regresaron de Babilonia (Nehemías 12:7). La tradición textual muestra cierta variación: el versículo 20 del mismo capítulo presenta la forma alternativa Salai, y la Septuaginta refleja ligeras diferencias en la transliteración. Estas variantes son comunes en los nombres propios hebreos y no alteran la identificación del personaje como parte del liderazgo sacerdotal de la restauración.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5543c', 'spa', 'Salú — líder simeonita, padre de Zimri', 'Salú fue un príncipe de la tribu de Simeón cuyo hijo Zimri se hizo tristemente célebre en la historia de Israel. Cuando Israel acampaba en Sitim, Zimri introdujo a una mujer madianita en el campamento desafiando abiertamente a Moisés, lo que provocó un juicio divino mediante una plaga. El sacerdote Finees mató a Zimri y a la mujer, deteniendo así la plaga. El nombre aparece únicamente en el contexto de este trágico relato.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5543e', 'spa', 'a Salai — frase preposicional que señala un nombre sacerdotal', 'Esta forma combina la preposición hebrea ''a'' con el nombre propio Salai, identificado como sacerdote. La aparición vincula a esta figura con Salú en Nehemías 12:7, reflejando al mismo individuo bajo una ligera variación del nombre. Tales construcciones preposicionales con nombres propios son habituales en las listas genealógicas y administrativas donde se especifican relaciones o asignaciones entre personas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5545', 'spa', 'Perdonar, indultar (siempre con sujeto divino); ser perdonado (Nifal pasivo del perdón divino).', 'Perdonar, indultar (siempre con sujeto divino); ser perdonado (Nifal pasivo del perdón divino).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5546', 'spa', 'perdonador — dispuesto a otorgar perdón y mostrar misericordia', 'Este adjetivo describe el carácter de Dios como fundamentalmente inclinado al perdón más que al juicio. El salmista declara esta cualidad junto con la bondad divina en una oración pidiendo misericordia. El hebreo enfatiza no solo la capacidad de perdonar, sino la disposición y voluntad de hacerlo. La evidencia interlingüística muestra un énfasis constante en el aspecto del perdón, y el español capta bien este matiz con el sustantivo agentivo ''perdonador''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5547', 'spa', 'Perdón, indulgencia; gracia divina que absuelve el pecado', 'Este sustantivo hebreo tardío significa perdón o indulgencia. Nehemías 9:17 alaba a Dios como «Dios de perdones» (plural de intensidad), abundante en gracia pese a la rebeldía de Israel. Salmo 130:4 declara: «contigo hay perdón, para que seas temido», donde el perdón divino produce reverencia, no presunción. Daniel 9:9 confiesa: «del Señor nuestro Dios son las misericordias y los perdones», reconociendo la misericordia como atributo divino. Las formas plurales en Nehemías y Daniel subrayan un perdón abundante y reiterado. La palabra aparece solo en textos bíblicos tardíos, reflejando un vocabulario teológico postexílico forjado en las duras lecciones del destierro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5548', 'spa', 'Salca; ciudad en el límite oriental de Basán, identificada con la moderna Salkhad', 'Salca (o Salkhad) era una ciudad que marcaba el límite oriental del territorio de Basán, posteriormente asignada a Gad o Manasés. Aparece en Deuteronomio 3:10 y Josué 12:5, 13:11 como punto de referencia fronterizo, y en 1 Crónicas 5:11 en relación con el territorio de Gad. El sitio se identifica con la moderna Salkhad, ubicada en el extremo sur del Jebel Haurán, a unos 100 kilómetros al este del río Jordán. La Estela Moabita también menciona un nombre similar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5549', 'spa', 'Levantar, construir un camino o calzada; por extensión, ensalzar en alabanza; también apilar o amontonar', 'Verbo arraigado en el acto físico de levantar tierra para formar una calzada o camino elevado. En Isaías 57:14 y 62:10 aparece como imperativo urgente para preparar el camino del SEÑOR, despejando piedras y construyendo la calzada. Las formas Piel e Hitpael extienden el significado hacia la alabanza y la autoexaltación: el Salmo 68:4 llama a los adoradores a «entonad cánticos» a Dios, mientras que Éxodo 9:17 describe a Faraón «enalteciéndose a sí mismo». La raíz abarca así tanto la preparación física de caminos como la elevación figurada en la alabanza o la arrogancia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5550', 'spa', 'Terraplén de asedio, rampa de asedio — un terraplén de tierra levantado contra las murallas de una ciudad durante un asalto militar', 'El sustantivo סֹלְלָה (solelah) designa la rampa o terraplén de asedio que los ejércitos antiguos construían para tomar ciudades fortificadas. Los atacantes amontonaban tierra, escombros y madera contra la muralla hasta que los soldados y arietes podían alcanzar las defensas superiores. El término aparece exclusivamente en contextos militares: Joab levanta uno contra Abel Bet-Maacá (2 Sam 20:15), los asirios amenazan Jerusalén con uno (2 Re 19:32; Is 37:33) y el asedio simbólico de Ezequiel incluye un terraplén (Ez 4:2). Jeremías lo usa repetidamente para las obras de asedio babilónicas alrededor de Jerusalén (Jer 6:6; 32:24; 33:4).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5551', 'spa', 'escalera — estructura para ascender y descender', 'La escalera aparece en la célebre visión de Jacob en Betel, donde vio una estructura asentada en la tierra que llegaba hasta el cielo, con ángeles que subían y bajaban por ella. Esta única aparición bíblica se convirtió en fundamento para comprender la conexión entre cielo y tierra, el acceso divino y el papel mediador que desempeñarían los descendientes de Jacob. El término designa específicamente un medio construido para escalar, ya sea una escalera sencilla o una escalinata más elaborada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5552', 'spa', 'ramas/cestos — término discutido en contexto vitícola', 'Este término poco frecuente aparece en el oráculo de Jeremías que compara a Israel con una viña, con incertidumbre textual sobre su significado exacto. Las versiones antiguas se inclinaron por ''cestos'' (para recoger uvas), mientras que muchos estudiosos modernos prefieren ''brotes'' o ''ramas'' basándose en el contexto y en lenguas semíticas comparadas. La imagen evoca la mano del rebuscador que vuelve para recoger lo que queda, ya sea para desnudar las ramas o para llenar cestos con fruto. La ambigüedad refleja su condición de hápax legómenon.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5553', 'spa', 'Peñasco, risco o formación rocosa grande; metafóricamente, Dios como refugio seguro; también la ciudad edomita Sela (Petra).', 'Peñasco, risco o formación rocosa grande; metafóricamente, Dios como refugio seguro; también la ciudad edomita Sela (Petra).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5554', 'spa', 'Sela, ciudad fortaleza en Edom; posiblemente Petra', 'Este topónimo designa un sitio fortificado en Edom, identificado tradicionalmente con Petra (del griego «petra» = roca), aunque los estudiosos modernos debaten esta identificación. Jueces 1:36 lo señala como frontera amorreo. Segundo Reyes 14:7 registra que Amasías capturó «Sela» y la renombró Jocteel, caso inusual de un conquistador rebautizando una ciudad. Isaías 16:1 lo usa geográficamente: «enviad el cordero al gobernante, desde Sela por el desierto». El nombre significa «roca» o «peñasco», acorde con la imponente geología de la región. Ya sea la famosa ciudad rosa o cualquier otra fortaleza edomita, Sela representa las alturas estratégicas e inexpugnables de Edom.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5556', 'spa', 'langosta comestible — insecto alado limpio, posiblemente la langosta calva', 'Este término designa un tipo específico de langosta considerada limpia y permitida como alimento según la ley levítica. Su nombre probablemente deriva de una raíz que significa ''tragar'' o ''consumir'', acorde con la voracidad característica de las langostas. Levítico 11:22 lo enumera entre cuatro variedades de langosta que los israelitas podían comer, junto con el אַרְבֶּה, el חַרְגֹּל y el חָגָב. La identificación precisa de la especie sigue siendo incierta, aunque la denominación ''langosta calva'' sugiere rasgos de apariencia distintivos reconocibles para los observadores antiguos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5557', 'spa', 'Torcer, pervertir, derribar (Piel); distorsionar la justicia, subvertir el orden moral o arruinar al impío.', 'Verbo en Piel que significa torcer, pervertir o trastornar, empleado tanto en contextos jurídicos como sapienciales. En la Torá describe cómo el soborno «pervierte» las palabras del justo (Éx 23:8; Dt 16:19), principio tan vital que se enuncia dos veces. En la literatura sapiencial adquiere una dimensión moral más amplia: la necedad «tuerce» el camino de la persona (Pr 19:3), la maldad «derriba» al pecador (Pr 13:6), y Dios mismo «trastorna» los planes del traicionero (Pr 22:12). Job 12:19 extiende este sentido al ámbito cósmico, donde Dios «derriba» incluso a los poderosos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5559', 'spa', 'subir, ascender, surgir (arameo); de un movimiento ascendente físico o figurado', 'Verbo arameo que significa subir o ascender, presente exclusivamente en Daniel y Esdras. Describe a las cuatro grandes bestias que suben del mar en la visión de Daniel (Dn 7:3), al cuerno pequeño que surge entre los diez (Dn 7:8, 20) y a los pensamientos que ascienden a la mente de Nabucodonosor en su lecho (Dn 2:29). En Esdras 4:12 informa que los judíos han ''subido'' del exilio a Jerusalén. Las formas españolas ''subiendo,'' ''subieron,'' ''subió'' reflejan de manera uniforme el movimiento ascendente, ya sea literal o figurado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5560', 'spa', 'Flor de harina (sémola), la harina de trigo de máxima calidad usada en las ofrendas de cereal, el ritual del templo y la cocina de élite.', 'Flor de harina (sémola), la harina de trigo de máxima calidad usada en las ofrendas de cereal, el ritual del templo y la cocina de élite.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5561', 'spa', 'Especias, sustancias aromáticas: ingredientes fragantes usados en el incienso sagrado y el aceite de unción.', 'Especias, sustancias aromáticas: ingredientes fragantes usados en el incienso sagrado y el aceite de unción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5563', 'spa', 'Flor de la vid; brotes que aparecen antes de que se forme el fruto', 'Este sustantivo designa la flor o brote de la vid en la etapa más temprana de la fructificación, cuando los diminutos racimos apenas aparecen. El Cantar de los Cantares lo emplea tres veces con imaginería romántica y agrícola. «Las vides están en cierne» (2:13) señala la llegada de la primavera y el despertar del amor. «Cazadnos las zorras... que arruinan las viñas, porque nuestras viñas están en cierne» (2:15) advierte contra las amenazas al amor joven, como depredadores que acechan vides tiernas. «Veamos si... han brotado las flores de la vid» (7:12) invita a contemplar el avance primaveral, donde la viticultura funciona como metáfora del romance. La palabra captura ese momento delicado en que la vid florece antes de dar fruto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5564', 'spa', 'Apoyarse sobre, imponer las manos, sostener, sustentar; abarca la imposición ritual de manos, el sustento divino, el apoyo físico y la firmeza estable', 'Apoyarse sobre, imponer las manos, sostener, sustentar; abarca la imposición ritual de manos, el sustento divino, el apoyo físico y la firmeza establecida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5565', 'spa', 'Semaquías — portero coraíta, nombre que significa ''Yahvé ha sostenido''', 'Semaquías sirvió como uno de los porteros coraítas en el servicio del templo durante el período postexílico. Su nombre es teofórico: combina la raíz verbal que significa ''sostener/apoyar'' con el nombre divino Yahvé, declarando así ''Yahvé ha sostenido''. Tales nombres solían conmemorar la ayuda divina en circunstancias difíciles, quizás la supervivencia de la familia a través del exilio. La Septuaginta lo traduce con las adaptaciones fonéticas griegas habituales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5566', 'spa', 'imagen, ídolo; figura o estatua erigida para adoración o veneración', 'Sustantivo que designa una imagen tallada o esculpida, posiblemente originado como nombre de una deidad extranjera antes de convertirse en término genérico para estatuas idolátricas. En Deuteronomio 4:16, Moisés advierte contra fabricar cualquier figura semejante, vinculándolo con la prohibición general de la idolatría. Manasés coloca un ídolo de este tipo en el Templo mismo (2 Cr 33:7) y luego lo retira en arrepentimiento (2 Cr 33:15). Ezequiel se encuentra con la provocadora «imagen de los celos» junto a la puerta norte del Templo (Ez 8:3, 5), un ídolo tan ofensivo que despierta la ira celosa de Dios. El cognado fenicio confirma su uso como término estándar para imágenes cultuales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5567', 'spa', 'en su lugar señalado — término disputado para la colocación del grano', 'Esta forma participial aparece en la descripción agrícola de Isaías, pero presenta considerables dificultades textuales. El texto masorético sugiere grano plantado ''en su lugar designado'' o ''en un área señalada'', pero la Septuaginta carece de esta palabra por completo y muchos eruditos la consideran una repetición accidental (ditografía) de la palabra precedente. Si es original, describiría una planificación agrícola cuidadosa donde la cebada recibe su ubicación apropiada. La incertidumbre hace que la traducción sea provisional.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5569', 'spa', 'erizado — áspero, con púas levantadas, usado para describir langostas', 'Este adjetivo describe un tipo distintivo de langosta en el oráculo de Jeremías contra Babilonia. La cualidad ''erizada'' probablemente se refiere a las vainas córneas que encierran las alas durante la fase de pupa, dándole a la criatura una apariencia rugosa y espinosa. Algunos intérpretes lo vinculan con la naturaleza agresiva y temible de los enjambres invasores de langostas. El término aparece una sola vez, caracterizando específicamente a las langostas convocadas para devastar Babilonia como juicio divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5570', 'spa', 'Senaá o Hassenaá; nombre de familia en Judá tras el exilio', 'Nombre propio de una familia judía que aparece en listas censales del período postexílico. En Esdras 2:35 y Nehemías 7:38 se documenta como uno de los grupos más numerosos entre los que regresaron de Babilonia. Nehemías 3:3 identifica su papel en la reconstrucción de la muralla de Jerusalén, específicamente en la edificación de la Puerta del Pescado. La variación entre «Senaá» y «Hassenaá» (con artículo definido) puede reflejar distintas tradiciones escribales o la incorporación del artículo al nombre propio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5571', 'spa', 'Sanbalat el horonita; gobernador samaritano que lideró la oposición a la reconstrucción de las murallas de Jerusalén por Nehemías', 'Nombre de origen acadio (Sin-uballit, ''Sin ha dado vida'') del gobernador de Samaria que se convirtió en el principal adversario de Nehemías. Sanbalat aparece exclusivamente en el libro de Nehemías, donde se burla de la obra de reconstrucción (Neh 2:10, 19), conspira con Tobías y Gesem contra los constructores (Neh 4:1, 7; 6:1-2) e intenta atraer a Nehemías a una trampa (Neh 6:5, 12, 14). Su hija se casó con un miembro de la familia sumo sacerdotal, lo que provocó que Nehemías expulsara al transgresor (Neh 13:28). La etimología babilónica del nombre refleja el carácter cosmopolita de la Samaria del período persa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5572', 'spa', 'Zarza espinosa o zarzal; la zarza ardiente desde la cual Dios habló a Moisés en Horeb.', 'Sustantivo masculino que designa una zarza espinosa, muy probablemente una zarzamora (rubus fruticosus), célebre por ser el arbusto que ardía sin consumirse cuando Dios se apareció a Moisés en el monte Horeb. Las seis ocurrencias se concentran en Éxodo 3:2-4, donde Moisés se aparta para contemplar el «gran espectáculo» de la zarza (seneh) en llamas pero intacta, y Deuteronomio 33:16 invoca «al que habitó en la zarza» como fórmula de bendición. La concentración de esta palabra en una sola teofanía la convierte prácticamente en un nombre propio en la conciencia hebrea. El significado teológico reside en lo que aconteció en ella, no en la planta misma.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5573', 'spa', 'Sené — nombre de un peñasco, posiblemente significa ''espinoso''', 'Sené era uno de dos peñascos rocosos prominentes que formaban un paso natural entre Micmas y Geba. Jonatán y su escudero ascendieron entre estos dos riscos —Sené y Boses— para lanzar su audaz ataque contra la guarnición filistea. El nombre puede derivar de una palabra que significa ''espina'' o ''arbusto espinoso'', sugiriendo el terreno escarpado e inhóspito. Este punto geográfico quedó asociado con una de las grandes victorias militares de Israel, lograda por fe y valentía.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5575', 'spa', 'ceguera repentina; pérdida sobrenatural de la vista como juicio divino', 'Este sustantivo en plural intensivo designa una ceguera repentina y sobrenatural, un golpe milagroso sobre los ojos. En Génesis 19:11, los ángeles hieren con ceguera a los hombres de Sodoma, que se agotan buscando a tientas la puerta sin encontrarla, como protección judicial para Lot y sus visitantes. En 2 Reyes 6:18, Eliseo ora: «Hiere a este pueblo con ceguera», y Dios ciega al ejército arameo de forma temporal, permitiendo la huida de Israel. En todos los casos no se trata de ceguera natural, sino de una pérdida total y súbita de visión enviada como juicio o protección divina. La forma plural sugiere intensidad: no un mero oscurecimiento, sino desorientación completa.');